  ["_CeladonMart2FCurrentFloorSignText"] = "Les objets de\npremier choix!\0121er: MARCHE DES\nDRESSEURS",
  ["_CeladonMart2FGirlText"] = "Equipe-toi de\nRAPPELS avant\011de partir à\011l'aventure.",
  ["_CeladonMart2FMiddleAgedManText"] = "Le SUPEREPOUSSE\ntient les faibles\011POKéMON à\011l'écart...\012C'est un REPOUSSE\nplus puissant!",
  ["_CeladonMart3FClerkReceivedTM18Text"] = "{PLAYER} reçoit\n{RAM:wStringBuffer}!",
  ["_CeladonMart3FClerkTM18ExplanationText"] = "CT18: RIPOSTE!\nBon allez...\011Bonne chance!",
  ["_CeladonMart3FClerkTM18NoRoomText"] = "Ton sac est plein\nà craquer!",
  ["_CeladonMart3FClerkTM18PreReceiveText"] = "J'ai fini!!!!\nJ'ai fini\011POKéMON!!!!\012Pas toi? Yahaha!\nPrends donc ceci,\011petit!",
  ["_CeladonMart3FCurrentFloorSignText"] = "2ème: JEUX VIDEO",
  ["_CeladonMart3FFightingGameText"] = "Kan contre Ryo!\nHadoh Ken!",
  ["_CeladonMart3FGameBoyKid1Text"] = "Tous les POKéMON\ncapturés ont un\011numéro d'immatri-\011culation et un\011nom de DO\011(Dresseur\011d'Origine)!",
  ["_CeladonMart3FGameBoyKid2Text"] = "Ouaiiis!\012Mon pote va\nm'échanger son\011KANGOUREX contre\011mon GRAVALANCH!",
  ["_CeladonMart3FGameBoyKid3Text"] = "Cool! Un\nGRAVALANCH!\012J'adore les\nGRAVALANCH!\012Qu...Hein??\012GRAVALANCH se\ntransforme en un\011autre POKéMON!",
  ["_CeladonMart3FLittleBoyText"] = "Le numéro d'imma-\ntriculation d'un\011POKéMON sert à\011l'identifier lors\011d'un échange!",
  ["_CeladonMart3FPokemonPosterText"] = "Rouge et Bleu!\nDeux POKéMON!",
  ["_CeladonMart3FPuzzleGameText"] = "Quatre lignes!\nEn un seul coup!",
  ["_CeladonMart3FRPGText"] = "Un RPG! Cool...\nMais trop dur!",
  ["_CeladonMart3FSNESText"] = "Une SUPER\nNINTENDO!",
  ["_CeladonMart3FSportsGameText"] = "Un jeu de sport!\nVive le foot!",
  ["_CeladonMart4FCurrentFloorSignText"] = "Un cadeau...\nL'amour...\011La vie!\0123ème: CADEAUX\012Vive les\névolutions!\011Les PIERRES sont\011en vente!",
  ["_CeladonMart4FSuperNerdText"] = "J'offre une belle\nPOKépoupée à ma\011copine!",
  ["_CeladonMart4FYoungsterText"] = "Ecoute donc...\012Tu peux fuir face\naux POKéMON\011sauvages en les\011occupant avec une\011POKéPOUPEE!",
  ["_CeladonMart5FCurrentFloorSignText"] = "4ème: MEDICAMENTS",
  ["_CeladonMart5FGentlemanText"] = "Les accélérateurs\nde POKéMON sont\011en vente ici.\012Le CALCIUM\naugmente les\011capacités\011SPECIALES.\012Le CARBONE\naugmente la\011VITESSE.",
  ["_CeladonMart5FSailorText"] = "J'veux acheter un\naccélérateur de\011POKéMON!\012Une PROTEINE\naugmentera\011l'ATTAQUE.\012Le FER augmente\nla DEFENSE!",
  ["_CeladonMartRoofCurrentFloorSignText"] = "DERNIER ETAGE:\nDISTRIBUTEURS",
  ["_CeladonMartRoofLittleGirlGiveHerADrinkText"] = "N'ai soif!\nNe veux boire!",
  ["_CeladonMartRoofLittleGirlGiveHerWhichDrinkText"] = "Quelle boisson\nlui offrir?",
  ["_CeladonMartRoofLittleGirlImNotThirstyText"] = "Heu...\nNon merci.\011A pu soif!",
  ["_CeladonMartRoofLittleGirlImThirstyText"] = "N'ai soif!\nNe veux boire!",
  ["_CeladonMartRoofLittleGirlNoRoomText"] = "Plus de place!",
  ["_CeladonMartRoofLittleGirlReceivedTM13Text"] = "{PLAYER} reçoit\n{RAM:wStringBuffer}!",
  ["_CeladonMartRoofLittleGirlReceivedTM48Text"] = "{PLAYER} reçoit\n{RAM:wStringBuffer}!",
  ["_CeladonMartRoofLittleGirlReceivedTM49Text"] = "{PLAYER} reçoit:\nCT49!",
  ["_CeladonMartRoofLittleGirlTM13ExplanationText"] = "\012{RAM:wStringBuffer}:\nLASER GLACE!\012Cette attaque\npourra geler\011l'ennemi!",
  ["_CeladonMartRoofLittleGirlTM48ExplanationText"] = "\012{RAM:wStringBuffer}:\nEBOULEMENT!\012Cette attaque\npeut faire peur\011à l'ennemi!",
  ["_CeladonMartRoofLittleGirlTM49ExplanationText"] = "\012TM49...\nTRIPLATTAQUE!",
  ["_CeladonMartRoofLittleGirlYayFreshWaterText"] = "Ouais ouais!\012DE L'EAU!\012C'est cool!\012Tiens...c'est\npour toi!",
  ["_CeladonMartRoofLittleGirlYayLemonadeText"] = "Ouaiiis!\012D'la LIMONADE!\012Top top top!\012V'là pour toi!",
  ["_CeladonMartRoofLittleGirlYaySodaPopText"] = "Ouaiiis!\012Du SODA COOL!\012Merciiii!\012Tiens, prends ça!",
  ["_CeladonMartRoofSuperNerdText"] = "Ma soeur est\ndresseur. Tu le\011crois, ça?\012Mais c'est une\np'tite peste!\011Elle m'agace!",
  ["_CeladonPokecenterBeautyText"] = "J'ai pris la\nPISTE CYCLABLE\011depuis PARMANIE!",
  ["_CeladonPokecenterGentlemanText"] = "La POKéFLUTE\nréveille les\011POKéMON grâce aux\011ultrasons!",
  ["_CeruleanBadgeHouseBoulderBadgeText"] = "L'ATTAQUE de tous\ntes POKéMON est\011augmentée.\012Il permet aussi\nd'utiliser la CS\011FLASH.",
  ["_CeruleanBadgeHouseCascadeBadgeText"] = "Les POKéMON d'un\nniveau inférieur\011à 30 t'obéiront.\012S'ils sont d'un\nniveau supérieur,\011ils seront\011incontrôlables!\012Tu pourras aussi\nutiliser la CS\011COUPE en-dehors\011des combats.",
  ["_CeruleanBadgeHouseEarthBadgeText"] = "Tous les POKéMON\nobéiront à tes\011ordres!",
  ["_CeruleanBadgeHouseMarshBadgeText"] = "Les POKéMON de\nniveau 70 ou\011moins t'obéiront.\012S'ils sont d'un\nniveau supérieur,\011ils seront\011incontrôlables!",
  ["_CeruleanBadgeHouseMiddleAgedManText"] = "Les BADGES sont\nportés par des\011dresseurs de haut\011niveau.\012Mmm... Tu en as\nau moins un.\012Ces BADGES ont\nd'étranges\011pouvoirs!",
  ["_CeruleanBadgeHouseMiddleAgedManVisitAnyTimeText"] = "Reviens me voir\nquand tu veux.",
  ["_CeruleanBadgeHouseMiddleAgedManWhichBadgeText"] = "Dis-moi...\012Lequel des 8\nBADGES veux-tu\011que je décrive?",
  ["_CeruleanBadgeHouseRainbowBadgeText"] = "Les POKéMON\njusqu'au niveau\01150 t'obéiront.\012Ceux d'un niveau\nsupérieur seront\011incontrôlables!\012Tu pourras aussi\nutiliser la CS\011FORCE.",
  ["_CeruleanBadgeHouseSoulBadgeText"] = "La DEFENSE de\ntous tes POKéMON\011sera augmentée.\012Tu pourras aussi\nutiliser la CS\011SURF en-dehors\011des combats.",
  ["_CeruleanBadgeHouseThunderBadgeText"] = "La VITESSE de\ntous tes POKéMON\011sera un peu\011augmentée.\012Tu pourras aussi\nutiliser la CS\011VOL en-dehors des\011combats.",
  ["_CeruleanBadgeHouseVolcanoBadgeText"] = "Le SPECIAL de tes\nPOKéMON sera un\011peu augmenté.",
  ["_CeruleanCityBikeShopSign"] = "Plus vite que le\nvent, plus vite\011dans les villes!\011...CYCLES A GOGO",
  ["_CeruleanCityCooltrainerF1SlowbroPunchText"] = "FLAGADOSS, cogne!\nMais non! Tu fais\011n'importe quoi!",
  ["_CeruleanCityCooltrainerF1SlowbroUseSonicboomText"] = "Allez! FLAGADOSS!\nAttaque! Attaque!\011Mais non!!! Tu\011m'écoutes, oui?",
  ["_CeruleanCityCooltrainerF1SlowbroWithdrawText"] = "FLAGADOSS, REPLI!\nNon! Pas ça!\012Pfff... C'est dur\nde contrôler un\011POKéMON!\012Seuls les bons\ndresseurs se font\011obéir par leurs\011POKéMON!",
  ["_CeruleanCityCooltrainerF2Text"] = "Ze veux une zolie\nBICYCLETTE!\012Ze la veux toute\nrouze!",
  ["_CeruleanCityCooltrainerMText"] = "T'es un dresseur?\nCapturer...\011Collectionner...\011Se friter...\011Dur, hein?",
  ["_CeruleanCityGuardText"] = "Ces pauvres gens\nont été volés.\012L'odieuse TEAM\nROCKET est\011derrière tout ça.\011C'est sûr!\012Même les forces\nde police ont du\011mal à lutter!",
  ["_CeruleanCityGymSign"] = "AZURIA\nARENE POKéMON\011CHAMPION: ONDINE\012La petite pest...\nHeu...sirène!",
  ["_CeruleanCityRivalDefeatedText"] = "Houlà!\nCalmos minable!\011T'as gagné, OK!",
  ["_CeruleanCityRivalIWentToBillsText"] = "{RIVAL}: Hé!\nTu sais quoi?\012Chuis allé chez\nLEO et y m'a tout\011montré ses\011POKéMON rares!\012Ca m'a rajouté\nplein d'pages sur\011mon bô POKéDEX!\012Tout l'monde sait\nque LEO est un\011POKéMANIAC!\012Il a même inventé\nle stockage des\011POKéMON par PC!\012T'as qu'à aller\nl'voir!\012Bon, je trace.\nTchao minab'!",
  ["_CeruleanCityRivalPreBattleText"] = "{RIVAL}: Yo!\n{PLAYER}!\012Alors tu t'en\nsors?\012Moi c'est l'pied!\nJ'ai chopé un tas\011de POKéMON méga\011puissants et\011tétra balèzes!\012Fais-moi voir\nc'que t'as, p'tit\011minable!",
  ["_CeruleanCityRivalVictoryText"] = "Pfff!\nUne perte de\011temps. Mi-nable!",
  ["_CeruleanCityRocketIBetterGetMovingText"] = "\012J'décampe...\nBye bye!",
  ["_CeruleanCityRocketIGiveUpText"] = "Stop!\nJ'me rends!\011T'es trop fort!",
  ["_CeruleanCityRocketIllReturnTheTMText"] = "OK! Voilà la CT\nqu'j'ai volée!",
  ["_CeruleanCityRocketReceivedTM28Text"] = "{PLAYER} récupère\nCT28!",
  ["_CeruleanCityRocketTM28NoRoomText"] = "Tu portes trop\nd'trucs!\012Je dois te donner\nça avant d'fuir.\011C'est écrit dans\011l'histoire!",
  ["_CeruleanCityRocketText"] = "Hé le lutin!\nC'est pas chez\011toi, ici...\011Quoi? Moi?\012J'suis innocent!\nHein? Quoi dit?\011Tu m'crois pas?\011Tu m'cherches?",
  ["_CeruleanCitySignText"] = "AZURIA\nBaignée par une\011aura d'un bleu\011mystérieux",
  ["_CeruleanCitySlowbroIgnoredOrdersText"] = "FLAGADOSS ignore\nles ordres...",
  ["_CeruleanCitySlowbroIsLoafingAroundText"] = "FLAGADOSS\nflâne...",
  ["_CeruleanCitySlowbroTookASnoozeText"] = "FLAGADOSS pionce\ncomme une masse.",
  ["_CeruleanCitySlowbroTurnedAwayText"] = "FLAGADOSS se\nbalade...",
  ["_CeruleanCitySuperNerd1Text"] = "Ce buisson devant\nla boutique blo-\011que le passage.\012Il doit y avoir\nun moyen de\011passer.",
  ["_CeruleanCitySuperNerd2Text"] = "Tu fais une\nencyclopédie sur\011les POKéMON?\011Pas mal...",
  ["_CeruleanCitySuperNerd3Text"] = "Des POKéMON trop\npuissants vivent\011dans la CAVE\011AZUREE!\012Seul le CHAMPION\nde la LIGUE\011POKéMON a le\011droit d'y entrer!",
  ["_CeruleanCityTrainerTipsText"] = "ASTUCE\012Appuyer sur B\npendant une évo-\011lution l'annule.",
  ["_CeruleanGymAfterBattleText1"] = "Tu dois te battre\ncontre d'autres\011dresseurs pour\011connaître ton\011niveau.",
  ["_CeruleanGymAfterBattleText2"] = "ONDINE est super\nforte!\012Elle ne va pas\nse faire avoir\011par un rigolo\011comme toi!",
  ["_CeruleanGymBattleText1"] = "Je suis très\nbalèze!\012ONDINE attendra!",
  ["_CeruleanGymBattleText2"] = "Plaouff!\012J'suis preums!\nBaston!",
  ["_CeruleanGymEndBattleText1"] = "Oh!\nJ'me suis fait\011écraser!",
  ["_CeruleanGymEndBattleText2"] = "Glargh!\nC'est dingue!",
  ["_CeruleanGymGymGuideBeatMistyText"] = "Tu as battu\nONDINE! Génial!\012Toi et moi, on\nforme une super\011équipe!",
  ["_CeruleanGymGymGuideChampInMakingText"] = "Salut à toi!\nFutur champion!\012Un conseil?\012La CHAMPIONNE,\nONDINE, est une\011spécialiste des\011POKéMON de l'eau!\012Absorbe l'eau\navec des POKéMON\011des plantes!\012Ou grille-les\navec de\011l'électricité!",
  ["_CeruleanGymMistyCascadeBadgeInfoText"] = "Le BADGECASCADE\noblige tous les\011POKéMON d'un\011niveau inférieur\011à 30 à t'obéir!\012Les échangés\naussi!\012En plus, tu peux\nmaintenant\011utiliser la CS\011COUPE!\012Tu peux COUPER\nles arbustes\011et ouvrir de\011nouveaux chemins!\012Tu gagnes aussi ma\nCT favorite!",
  ["_CeruleanGymMistyPreBattleText"] = "Salut! T'es un\nnouveau!\012Si tu veux être\nun vrai dresseur,\011il te faut une\011stratégie pour\011tes POKéMON!\012C'est quoi ta\ntactique pour\011capturer les\011POKéMON sauvages?\012Moi je leur fonce\ndans le tas avec\011mes POKéMON\011aquatiques!",
  ["_CeruleanGymMistyReceivedCascadeBadgeText"] = "Whouha!\nT'es super fort!\012Très bien!\012Je te donne le\nBADGECASCADE pour\011m'avoir battue!",
  ["_CeruleanGymMistyReceivedTM11Text"] = "{PLAYER} reçoit\nla CT11!",
  ["_CeruleanGymMistyTM11ExplanationText"] = "La CT11 contient\nBULLES D'O!\012Apprends-la à un\nPOKéMON de l'eau!",
  ["_CeruleanGymMistyTM11NoRoomText"] = "Ton inventaire\nest plein!",
  ["_CeruleanMartCooltrainerFText"] = "As-tu déjà vu des\nSUPER BONBONS??\012Quand un POKéMON\nen mange un, il\011gagne un niveau!",
  ["_CeruleanMartCooltrainerMText"] = "Le REPOUSSE tient\nles POKéMON\011sauvages à\011l'écart.\012Mets tes POKéMON\nles plus costauds\011en premier pour\011une plus grande\011efficacité!",
  ["_CeruleanPokecenterGentlemanText"] = "Tu connais LEO?\012On raconte que\nc'est un vrai\011POKéMANIAC!\012Les gens sont\njaloux de LEO.\012Nous sommes tous\ndes POKéMANIACs,\011non?",
  ["_CeruleanPokecenterGuyText"] = "LEO a une sacrée\ncollection de\011POKéMON!\012Et des rares, en\nplus...",
  ["_CeruleanPokecenterSuperNerdText"] = "Sacré LEO!\012Il donnerait\nn'importe quoi\011pour mettre la\011main sur un\011POKéMON rare!",
  ["_CeruleanTradeHouseGrannyText"] = "Mon mari aime\nles échanges de\011POKéMON.\012Si tu aimes\ncollectionner,\011fais des échanges\011avec lui, OK?",
  ["_CeruleanTrashedHouseFishingGuruTheyStoleATMText"] = "Ces ROCKET, ils\nsont si méchants!\012Regarde ce qu'ils\nont fait ici!\012Ils m'ont volé\nune CT pour\011apprendre à leurs\011POKéMON à\011creuser des\011TUNNELS!\012Ca m'a coûté les\nyeux de la tête!",
  ["_CeruleanTrashedHouseFishingGuruWhatsLostIsLostText"] = "Contre mauvaise\nfortune bon\011coeur!\012Je vais apprendre\nà mon TAUPIQUEUR\011à creuser des\011TUNNELS sans CT!",
  ["_CeruleanTrashedHouseGirlText"] = "La TEAM ROCKET\ndoit maintenant\011creuser des\011TUNNELS dans tout\011ce qui bouge!",
  ["_CeruleanTrashedHouseWallHoleText"] = "La TEAM ROCKET a\ncreusé une\011nouvelle sortie!",
  ["_ChampionsRoomOakComeWithMeText"] = "CHEN: {PLAYER}!\012Cette victoire...\nTu ne la dois pas\011entièrement à tes\011qualités!\012Tu as tant baigné\nd'amour tes chers\011petits POKéMON!\012Et ça... \nC'est bien. \011{PLAYER}!\011Suis-moi!",
  ["_ChampionsRoomOakCongratulatesPlayerText"] = "CHEN: Tu as gagné!\nFélicitations!\011Tu es le nouveau\011champion de la\011LIGUE POKéMON!\012Tu as tant changé\ndepuis ton départ\011avec {RAM:wNameBuffer}!\012{PLAYER}, tu es\ngrand maintenant!",
  ["_ChampionsRoomOakDisappointedWithRivalText"] = "CHEN: {RIVAL}!\nJe suis... déçu!\012Apprenant que tu\navais vaincu le\011CONSEIL des 4, je\011suis venu en\011vitesse!\012Mais le temps\nd'arriver jusqu'\011ici, tu avais\011déjà perdu...\011C'est dingue!\012{RIVAL}! As-tu\ncompris pourquoi\011ton équipe s'est\011fait moucher?\012Tu as oublié de\ntraiter tes\011POKéMON avec\011amour!\012Et oui mon p'tit\nbonhomme.\011C'est comme ça et\011pis c'est tout!",
  ["_ChampionsRoomOakText"] = "CHEN: {PLAYER}!",
  ["_ChampionsRoomRivalAfterBattleText"] = "Qu...Comm...Hein?\nMoi? Pourquoi?\011WHAAAAAAAAAAA!\012J'ai entraîné mes\nPOKéMON à la\011perfection...\012Et zut alors!\nTu es le nouveau\011champion POKéMON!\012Alors ça...\nCa me la coupe.",
  ["_ChampionsRoomRivalIntroText"] = "{RIVAL}:\nBonjour minable.\012Je t'attends\ndepuis une bonne\011plombe, {PLAYER}!\012Ton devoir en\ntant que rival\011est d'entraîner\011mes POKéMON.\012En améliorant mon\nPOKéDEX, j'ai\011recherché les\011POKéMON sur-\011puissants!\012J'ai ainsi créé\nl'équipe ultime,\011efficace contre\011tous les types de\011POKéMON!\012Ca t'épate, hein?\012Je suis le\nchampion POKéMON!\012Tu sais c'que ça\nveut dire?\012Ecoute ça,\nminable!\012Je suis le\ndresseur le plus\011puissant du\011monde! Yaaa!",
  ["_ChanseyDexEntry"] = "Un POKéMON rare\net difficile à\ncapturer qui\012porte chance et\nbien-être à son\npossesseur.",
  ["_ChargeMoveEffectText"] = "{USER}",
  ["_CharizardDexEntry"] = "Il peut fondre\nla roche de son\nsouffle brûlant.\012Il est souvent la\ncause de nombreux\nincendies.",
  ["_CharmanderDexEntry"] = "Il préfère les\nendroits chauds.\nEn cas de pluie,\012de la vapeur\nse forme autour\nde sa queue.",
  ["_CharmeleonDexEntry"] = "En agitant sa\nqueue, il peut\nélever le niveau\012de la température\nà un degré\nincroyable.",
  ["_ChooseABoxText"] = "Choisissez une\nBOITE POKéMON.",
  ["_CinnabarGymBlainePostBattleAdviceText"] = "DEFLAGRATION est\nla technique de\011feu ultime!\012Ne la donne pas\nà un POKéMON de\011l'eau, ça ferait\011pas bon ménage!",
  ["_CinnabarGymBlainePreBattleText"] = "Salutations.\012Mon nom est...\nAUGUSTE! Je suis\011le CHAMPION de\011l'ARENE de\011CRAMOIS'ILE!\012Mes POKéMON\nflamboyants vont\011te réduire en\011cendres!\012Haha! J'espère\nque tu as de\011l'ANTI-BRULE!\011Y va bientôt\011faire très chaud!",
  ["_CinnabarGymBlaineReceivedTM38Text"] = "{PLAYER} obtient:\n{RAM:wStringBuffer}!",
  ["_CinnabarGymBlaineReceivedVolcanoBadgeText"] = "Vlouff!\nJe me suis fait\011vaporiser!\012Tu as gagné le\nBADGE VOLCAN!",
  ["_CinnabarGymBlaineTM38ExplanationText"] = "\012CT38 :\nDEFLAGRATION!\012Elle convient à\nun POKéMON du\011feu!\012REPTINCEL ou\nPONYTA feront\011l'affaire!",
  ["_CinnabarGymBlaineTM38NoRoomText"] = "Ton inventaire\nest plein!",
  ["_CinnabarGymBlaineVolcanoBadgeInfoText"] = "Haha!\012Le BADGE VOLCAN\naugmente le\011SPECIAL de tes\011POKéMON!\012Prends ça aussi!",
  ["_CinnabarGymGymGuideBeatBlaineText"] = "{PLAYER}! Tu as\nbattu AUGUSTE!",
  ["_CinnabarGymGymGuideChampInMakingText"] = "Salut! Graine de\nchampion!\012AUGUSTE, le\nflamboyant, est\011un pro des\011POKéMON de feu!\012C'est le moment\nde jeter de\011l'eau sur le feu!\012Prends donc des\nANTI-BRULE avec\011toi! Ca peut\011toujours servir!",
  ["_CinnabarGymQuizCorrectText"] = "Bonne réponse!\012En avant!",
  ["_CinnabarGymQuizIncorrectText"] = "N'importe quoi!",
  ["_CinnabarGymQuizIntroText"] = "Quiz POKéMON!\012Une bonne réponse\nouvrira la porte!\012Une erreur et\nc'est la guerre!\012Pour préserver\nune équipe avant\011d'affronter le\011CHAMPION...\012Mieux vaut éviter\nles erreurs!",
  ["_CinnabarGymSuperNerd1AfterBattleText"] = "Le feu, ça brûle,\nles flammes, faut\011pas mettre la\011main d'dans...\012Brûle, brûle...\nJ'aime le feu...",
  ["_CinnabarGymSuperNerd1BattleText"] = "Un POKéMON du\nfeu, c'est chaud!",
  ["_CinnabarGymSuperNerd1EndBattleText"] = "Yaha!\nFait chaud, non?",
  ["_CinnabarGymSuperNerd2AfterBattleText"] = "Je vole, j'y peux\nrien. Je vole des\011POKéMON, et\011j'me marre bien!",
  ["_CinnabarGymSuperNerd2BattleText"] = "Avant, j'étais un\nvoleur, j'avais\011honte...\011Aujourd'hui je\011suis un dresseur\011et je suis fier!",
  ["_CinnabarGymSuperNerd2EndBattleText"] = "Ah!\nJ'ai honte, je me\011rends!",
  ["_CinnabarGymSuperNerd3AfterBattleText"] = "J'suis un\ncérébral, tu peux\011pas comprendre!",
  ["_CinnabarGymSuperNerd3BattleText"] = "Les POKéMON, je\nmaîtrise, alors\011toi, tu peux pas\011gagner!",
  ["_CinnabarGymSuperNerd3EndBattleText"] = "Ben...\nMais...ben...!",
  ["_CinnabarGymSuperNerd4AfterBattleText"] = "Si y'avait des\nPOKéMON voleurs,\011j'en aurais des\011tas! Moi, c'que\011j'aime, c'est les\011cambriolages!",
  ["_CinnabarGymSuperNerd4BattleText"] = "Les POKéMON du\nfeu, j'adore!",
  ["_CinnabarGymSuperNerd4EndBattleText"] = "Flouf!\nC'est l'feu!",
  ["_CinnabarGymSuperNerd5AfterBattleText"] = "Tout petit,\nAUGUSTE aimait se\011promener dans les\011montagnes.\011Un jour, il s'est\011perdu et il eut\011très froid! Mais\011un POKéMON de feu\011apparut...\012La lumière de ses\nailes enflammées\011permit à AUGUSTE\011de retrouver son\011chemin! Depuis\011il adore les\011POKéMON de feu!",
