  ["_NameRatersHouseNameRaterGiveItANiceNameText"] = "{RAM:wNameBuffer}?\nMouais, c'est pas\011mal!\012Mais tu voudrais\nque je lui donne\011un nom un peu...\011plus...qui aurait\011plus de......\011Mieux, quoi!\012Bon, alors?",
  ["_NameRatersHouseNameRaterPokemonHasBeenRenamedText"] = "OK! Ce POKéMON\na été renommé\011{RAM:wBuffer}!\012Oh, mais oui!\nC'est bien mieux\011qu'avant!",
  ["_NameRatersHouseNameRaterWantMeToRateText"] = "Salut tout le\nmonde! Je suis le\011GRAND DONNEUR DE\011NOMS!\012Dis-moi, petit,\ntu serais pas du\011genre à vouloir\011donner un p'tit\011nom à un de tes\011POKéMON?",
  ["_NameRatersHouseNameRaterWhatShouldWeNameItText"] = "Et alors, c'est\nquoi qu'on va lui\011donner comme nom\011à celui-là?",
  ["_NameRatersHouseNameRaterWhichPokemonText"] = "Quel POKéMON\nveux-tu renommer?",
  ["_NeedYourPokemonText"] = "OK! Confiez-nous\nvos POKéMON!",
  ["_NewBadgeRequiredText"] = "Non! Un nouveau\nBADGE est requis.",
  ["_NewBicycleText"] = "Une BICYCLETTE\ntoute neuve! Top!",
  ["_NidokingDexEntry"] = "Sa queue est une\narme redoutable,\nil s'en sert pour\012attraper sa proie\net lui broyer les\nos.",
  ["_NidoqueenDexEntry"] = "Ses écailles très\nrésistantes et\nson corps massif\012sont des armes\ndévastatrices.",
  ["_NidoranFDexEntry"] = "Ce POKéMON est\nhérissé de dards\nempoisonnés.\012Les femelles ont\ndes dards plus\npetits.",
  ["_NidoranMDexEntry"] = "Son ouïe très\nfine l'avertit du\ndanger. Plus\012ses cornes sont\ngrandes, plus son\npoison est mortel.",
  ["_NidorinaDexEntry"] = "La corne de la\nfemelle grandit\nlentement. Elle\012préfère attaquer\navec ses griffes\net sa gueule.",
  ["_NidorinoDexEntry"] = "Très agressif, il\nest prompt à\nrépondre à la\012violence. La\ncorne sur sa tête\nest venimeuse.",
  ["_NinetalesDexEntry"] = "Très intelligent\net rancunier.\nAttrapez-lui une\012de ses queues et\nil vous maudira\npour 1000 ans.",
  ["_NoCyclingAllowedHereText"] = "Interdit de\npédaler ici!!!",
  ["_NoEffectText"] = "Sans effet!",
  ["_NoMonText"] = "Hein? Il n'y a\naucun POKéMON!",
  ["_NoMoreRoomForItemText"] = "Votre inventaire\nest plein!",
  ["_NoMovesLeftText"] = "{RAM:wBattleMonNick} n'a\nplus d'attaques!",
  ["_NoNibbleText"] = "Même pas une\ntouche...",
  ["_NoRoomToStoreText"] = "Plus de place\npour stocker.",
  ["_NoRunningText"] = "On ne peut s'en-\nfuir d'un combat\011de dresseurs!",
  ["_NoSurfingHereText"] = "Pas de SURF sur\n{RAM:wNameBuffer} ici!",
  ["_NoTrade1Text"] = "Bon....\nTant pis...",
  ["_NoTrade2Text"] = "Mmmm...\nPas glop...",
  ["_NoTrade3Text"] = "Dommage.",
  ["_NoWillText"] = "Il ne veut pas\ncombattre!",
  ["_NotEnoughCoinsSlotMachineText"] = "Pas assez de\njetons!",
  ["_NotHealthyEnoughText"] = "Points de vie\ninsuffisants.",
  ["_NotThisTimeText"] = "Oups. Perdu!",
  ["_NotVeryEffectiveText"] = "Ce n'est pas très\nefficace...",
  ["_NothingHappenedText"] = "Rien ne se passe!",
  ["_NothingHereText"] = "On dirait qu'il\nn'y a rien ici.",
  ["_NothingStoredText"] = "Rien n'est\nstocké.",
  ["_NothingToCutText"] = "Il n'y a rien à\nCOUPER!",
  ["_NothingToDepositText"] = "Vous n'avez rien\nà stocker.",
  ["_OHKOText"] = "Super patate!",
  ["_OKExclamationText"] = "!",
  ["_OakLabEmailText"] = "Il y a un e-mail!\012...\012Avis à tous les\ndresseurs de\011POKéMON!\012Le CONSEIL des 4\nest prêt à punir\011tout concurrent!\012Présentez vos\nmeilleurs POKéMON\011et découvrez\011votre niveau\011en tant que\011dresseur!\012LIGUE POKéMON,\nPLATEAU INDIGO\012PS: PROF. CHEN,\nvotre visite est\011attendue...",
  ["_OakSpeechText1"] = "Bien le bonjour!\nBienvenue dans le\011monde magique des\011POKéMON!\012Mon nom est CHEN!\nLes gens souvent\011m'appellent le\011PROF POKéMON!",
  ["_OakSpeechText2A"] = "Ce monde est\npeuplé de\011créatures du nom\011de POKéMON!",
  ["_OakSpeechText2B"] = "\012Pour certains,\nles POKéMON sont\011des animaux\011domestiques, pour\011d'autres, ils\011sont un moyen de\011combattre.\012Pour ma part...\012L'étude des\nPOKéMON est\011ma profession.",
  ["_OakSpeechText3"] = "{PLAYER}!\012Ta quête des\nPOKéMON est sur\011le point de\011commencer!\012Un tout nouveau\nmonde de rêves,\011d'aventures et\011de POKéMON\011t'attend! Dingue!",
  ["_OaksAideComeBackText"] = "Dans ce cas...\012Reviens quand tu\nauras {NUM:hOaksAideRequirement, 1, 3} POKéMON\011différents pour\011obtenir\011{RAM:wOaksAideRewardItemName}.",
  ["_OaksAideGotItemText"] = "{PLAYER} obtient\n{RAM:wOaksAideRewardItemName}!",
  ["_OaksAideHereYouGoText"] = "Super! Tu as\n{NUM:hOaksAideNumMonsOwned, 1, 3} POKéMON\011différents!\011Félicitations!\012Voici ta\nrécompense!",
  ["_OaksAideHiText"] = "Salut! Tu te\nrappelles? Je\011suis l'assistant\011du Prof. Chen!\012Si tu attrapes \n{NUM:hOaksAideRequirement, 1, 3} POKéMON\011différents, je\011suis censé\011t'offrir...\011{RAM:wOaksAideRewardItemName}!\012Alors {PLAYER},\nas-tu attrapé au\011moins {NUM:hOaksAideRequirement, 1, 3} POKéMON\011différents?",
  ["_OaksAideNoRoomText"] = "Oh! Tu n'as plus\nde place pour\011{RAM:wOaksAideRewardItemName}.",
  ["_OaksAideUhOhText"] = "Voyons voir...\nOh! Tu n'as\011attrapé que {NUM:hOaksAideNumMonsOwned, 1, 3}\011POKéMON!\012Il t'en faut {NUM:hOaksAideRequirement, 1, 3}\ndifférents pour\011mériter...\011{RAM:wOaksAideRewardItemName}.",
  ["_OaksLabGirlText"] = "Le PROF. CHEN est\nla référence en\011matière de\011POKéMON!\012Il est très\nrespecté parmi\011les dresseurs de\011POKéMON!",
  ["_OaksLabGivePokeballsExplanationText"] = "\012Quand un POKéMON\nsauvage apparaît,\011il faut jouer\011serré.\012Lance-lui une\nPOKé BALL pour le\ncapturer!\012Mais ça ne\nmarchera pas à\011tous les coups!\012Un POKéMON en\npleine forme peut\011s'échapper!\011C'est ça, la\011grande aventure\011des POKéMON!",
  ["_OaksLabLastMonText"] = "C'est le dernier\nPOKéMON du\011PROF. CHEN!",
  ["_OaksLabMonEnergeticText"] = "Ce POKéMON est\ntrès énergique!",
  ["_OaksLabOak1ComeSeeMeSometimesText"] = "CHEN: Reviens me\nvoir de temps en\011temps.\012Tiens-moi informé\ndu niveau de ton\011POKéDEX.",
  ["_OaksLabOak1DeliverParcelText"] = "CHEN: {PLAYER}!\012Comment va ton\nPOKéMON?\012Je crois qu'il\nt'aime bien!\012Tu m'as l'air\ndoué pour\011entraîner les\011POKéMON!\012Comment? Tu as\nquelque chose à\011me donner?\012{PLAYER} donne\nle COLIS DE CHEN.",
  ["_OaksLabOak1HowIsYourPokedexComingText"] = "CHEN: Je suis\ncontent de te\011revoir. Où en\011es-tu avec ton\011POKéDEX?\011Voyons, voyons...",
  ["_OaksLabOak1ParcelThanksText"] = "\012Ah! C'est la\nPOKé BALL que\011j'ai commandée!\011Merci!",
  ["_OaksLabOak1PokemonAroundTheWorldText"] = "Les POKéMON du\nmonde entier sont\011à toi, {PLAYER}!",
  ["_OaksLabOak1RaiseYourYoungPokemonText"] = "CHEN: {PLAYER},\nentraîne ton\011POKéMON au combat\011pour qu'il\011devienne fort!",
  ["_OaksLabOak1ReceivedPokeballsText"] = "CHEN: Il ne te\nsuffit pas de\011voir un POKéMON\011pour tout savoir\011sur lui, mon\011p'tit bonhomme!\012Il te faut aussi\nl'attraper! Voici\011des POKé BALL\011pour en capturer.\012{PLAYER} obtient\n5 POKé BALL!",
  ["_OaksLabOak1WhichPokemonDoYouWantText"] = "CHEN: {PLAYER},\nquel POKéMON \011choisis-tu?",
  ["_OaksLabOak1YourPokemonCanFightText"] = "CHEN: Ton POKéMON\nte protègera des\011POKéMON sauvages!",
  ["_OaksLabOak2Text"] = "?",
  ["_OaksLabOakBePatientText"] = "CHEN: Patience,\n{RIVAL}! Tu en\011auras un aussi!",
  ["_OaksLabOakChooseMonText"] = "CHEN: {RIVAL}?\nHeu...\012Ah, c'est vrai!\nJe t'ai dit de\011venir...\012Tiens, {PLAYER}!\012Voici 3 POKéMON!\012Mais...\012Ils sont dans des\nPOKé BALL.\012Plus jeune,\nj'étais un sacré\011dresseur de\011POKéMON! Et oui!\012Mais avec l'âge,\nil ne m'en reste\011plus que 3!\011Choisis-en un!",
  ["_OaksLabOakDontGoAwayYetText"] = "CHEN: Hé! Ne pars\npas tout d'suite!",
  ["_OaksLabOakGotPokedexText"] = "CHEN: {PLAYER} et\n{RIVAL}! Prenez\011ces POKéDEX!\012{PLAYER} obtient\nle POKéDEX!",
  ["_OaksLabOakIHaveARequestText"] = "CHEN: Bon! J'ai\nune faveur à vous\011demander.",
  ["_OaksLabOakMyInventionPokedexText"] = "Il y a sur ce\nbureau mon\011invention...\011Le POKéDEX!\012Il enregistre les\ninformations sur\011les POKéMON\011rencontrés ou\011capturés!\012C'est comme une\nencyclopédie!",
  ["_OaksLabOakThatWasMyDreamText"] = "Faire un guide\ncomplet sur les\011POKéMON du monde\011entier...\012C'est mon rêve!\012Mais je suis trop\nvieux maintenant!\012C'est pourquoi je\nveux que vous\011terminiez mon\011travail!\012Allez, roulez\njeunesse!\012Que la grande\nquête des POKéMON\011commence!",
  ["_OaksLabPokedexText"] = "C'est comme une\nencyclopédie\011mais les pages\011sont blanches!",
  ["_OaksLabReceivedMonText"] = "{PLAYER} obtient:\n{RAM:wNameBuffer}!",
  ["_OaksLabRivalAmIGreatOrWhatText"] = "{RIVAL}: Yeah! Je\nsuis fort, hein?",
  ["_OaksLabRivalFedUpWithWaitingText"] = "{RIVAL}: Pépé!\nJ'en ai marre\011d'attendre!",
  ["_OaksLabRivalGoAheadAndChooseText"] = "{RIVAL}: Je ne\nsuis pas avide\011comme toi!\012Allez, choisis,\n{PLAYER}!",
  ["_OaksLabRivalGrampsIsntAroundText"] = "{RIVAL}: Yo!\n{PLAYER}! Pépé\011n'est pas là!",
  ["_OaksLabRivalGrampsText"] = "{RIVAL}: Pépé!",
  ["_OaksLabRivalIPickedTheWrongPokemonText"] = "QUOI???\nIncroyable!\011J'ai pas pris le\011bon POKéMON!",
  ["_OaksLabRivalIllTakeThisOneText"] = "{RIVAL}: Je\nprends celui-ci!",
  ["_OaksLabRivalIllTakeYouOnText"] = "{RIVAL}: Minute,\n{PLAYER}!\011Voyons lequel de\011nos POKéMON est\011le plus fort!\012Allez viens te\nbattre, minable!",
  ["_OaksLabRivalLeaveItAllToMeText"] = "{RIVAL}: OK,\npépé! Donne-les\011moi tous!\012{PLAYER}, c'est\nclair, j'ai pas\011besoin de toi,\011minable!\012Je sais! Je vais\nvoler une CARTE à\011ma soeur!\012Et je lui dirai\nde ne pas t'en\011donner une! Yark!",
  ["_OaksLabRivalMyPokemonLooksStrongerText"] = "{RIVAL}: Mon\nPOKéMON est\011plus fort.",
  ["_OaksLabRivalReceivedMonText"] = "{RIVAL} reçoit\nun {RAM:wNameBuffer}!",
  ["_OaksLabRivalSmellYouLaterText"] = "{RIVAL}: OK!\nJe vais entraîner\011mon POKéMON!\012{PLAYER}! Pépé!\nA plus tard!",
  ["_OaksLabRivalWhatAboutMeText"] = "{RIVAL}: Ben!\nPépé! Mon pépé!\011Et moi?",
  ["_OaksLabRivalWhatDidYouCallMeForText"] = "{RIVAL}: Pourquoi\ntu m'as appelé?",
  ["_OaksLabScientistText"] = "J'assiste le\nPROF. CHEN.\011Je suis donc son\011...ta daaa!...\011ASSISTANT!",
  ["_OaksLabThoseArePokeBallsText"] = "Ces POKé BALL\ncontiennent des\011POKéMON!",
  ["_OaksLabYouWantBulbasaurText"] = "Veux-tu le\nPOKéMON des\011plantes,\011BULBIZARRE?",
  ["_OaksLabYouWantCharmanderText"] = "Veux-tu le\nPOKéMON de feu,\011SALAMECHE?",
  ["_OaksLabYouWantSquirtleText"] = "Veux-tu le\nPOKéMON de l'eau,\011CARAPUCE?",
  ["_OddishDexEntry"] = "Pendant la\njournée il se\ncache sous terre.\012Il s'aventure la\nnuit pour planter\ndes graines.",
  ["_OhFineThenText"] = "Bon. Très bien.",
  ["_OlderFileWillBeErasedText"] = "L'ancienne\nsauvegarde sera\011effacée. OK?",
  ["_OmanyteDexEntry"] = "Disparu depuis\nlongtemps, il\npeut être réanimé\012génétiquement à\npartir d'anciens\nfossiles.",
  ["_OmastarDexEntry"] = "Un POKéMON\npréhistorique qui\ndisparut quand sa\012coquille devint\ntrop lourde à\ndéplacer.",
  ["_OnceReleasedText"] = "{RAM:wStringBuffer} sera\nà jamais perdu.\011Continuer?",
  ["_OneMoreGoSlotMachineText"] = "Encore une\nfois?",
  ["_OneTwoAndText"] = "1, 2 et...",
  ["_OnixDexEntry"] = "Les parties en\npierre de son\ncorps durcissent\012pour devenir\ncomme un diamant\nde couleur noire.",
  ["_OopsYouDontHaveEnoughRoomText"] = "Votre inventaire\nest plein.",
  ["_OutOfCoinsSlotMachineText"] = "Zut de flûte!\nPas de jetons!",
  ["_OutOfSafariBallsText"] = "Haut-parleur: Hé!\012Vous n'avez plus\nde SAFARI BALL!",
  ["_PPIncreasedText"] = "PP de {RAM:wStringBuffer}\naugmentés.",
  ["_PPMaxedOutText"] = "PP de {RAM:wStringBuffer}\nsont au max.",
  ["_PPRestoredText"] = "PP restaurés.",
  ["_PalletTownFisherText"] = "Le progrès...\nC'est dément!\012On peut désormais\nstocker et même\011retirer des\011objets ou des\011POKéMON via PC!",
  ["_PalletTownGirlText"] = "J'élève des\nPOKéMON, moi\011aussi!\012Une fois forts,\nils pourront me\011protéger!",
  ["_PalletTownOakHeyWaitDontGoOutText"] = "CHEN: Hé toi, là!\nNe pars pas!",
  ["_PalletTownOakItsUnsafeText"] = "CHEN: C'est super\ndangereux! Des\011POKéMON sauvages\011infestent les\011hautes herbes!\012Il te faut un\nPOKéMON pour te\011protéger...\011J'ai trouvé!\012Suis-moi!",
  ["_PalletTownOaksLabSignText"] = "LABO POKéMON\nDU PROF. CHEN",
  ["_PalletTownPlayersHouseSignText"] = "Maison de\n{PLAYER}",
  ["_PalletTownRivalsHouseSignText"] = "Maison de\n{RIVAL}",
  ["_PalletTownSignText"] = "BOURG PALETTE\nUn monde de\011couleurs s'ouvre\011à vous!",
  ["_ParalyzedMayNotAttackText"] = "{TARGET}\nest paralysé!\011Il peut ne pas\011attaquer!",
  ["_ParasDexEntry"] = "Les champignons\nsur son dos se\nnourrissent des\012nutriments de\nleur hôte\ninsectoïde.",
  ["_ParasectDexEntry"] = "Une symbiose\nentre un parasite\net un insecte. Le\012champignon a pris\nle contrôle de\nson hôte.",
  ["_ParlyzHealText"] = "{RAM:wNameBuffer}\npeut bouger!",
  ["_PartyMenuBattleText"] = "Faire combattre\nquel POKéMON?",
  ["_PartyMenuItemUseText"] = "Sur quel POKéMON?",
  ["_PartyMenuNormalText"] = "Sélectionnez un\nPOKéMON.",
  ["_PartyMenuSwapMonText"] = "Nouvelle position\ndu POKéMON...",
  ["_PartyMenuUseTMText"] = "Capsule sur quel\nPOKéMON?",
  ["_PersianDexEntry"] = "Très apprécié\npour sa fourrure,\nil est difficile\012à apprivoiser en\nraison de son\ncaractère rétif.",
  ["_PewterCityCooltrainerFText"] = "On raconte que\nles MELOFEE sont\011les habitants de\011la lune!\012Ils sont apparus\naprès la chute de\011la PIERRE LUNE\011sur le MONT\011SELENITE.",
  ["_PewterCityCooltrainerMText"] = "Il y a de très\nbons dresseurs\011par ici!\012Ils sont SCOUTS\npour la plupart\011mais PIERRE de\011l'ARENE d'ARGENTA\011est terrible!",
  ["_PewterCityGymSignText"] = "ARENE POKéMON\nd'ARGENTA\011CHAMPION: PIERRE\012L'dresseur dur\ncomme la pierre!\011Bonne blague.",
  ["_PewterCityMuseumSignText"] = "MUSEE DES\nSCIENCES\011d'ARGENTA",
  ["_PewterCityPokecenterGuyText"] = "(Baille)!\012Lorsque RONDOUDOU\nchante, tous les\011POKéMON piquent\011du nez...\012...Moi aussi...\n(Pionce)...",
  ["_PewterCityPoliceNoticeSignText"] = "AVIS!\012On nous signale\ndes voleurs de\011fossiles de\011POKéMON sur le\011MONT SELENITE.\011N'hésitez pas à\011contacter la\011POLICE d'ARGENTA!",
  ["_PewterCitySignText"] = "ARGENTA\nLe mat et le gris\011de la roche.",
  ["_PewterCitySuperNerd1DidYouCheckOutMuseumText"] = "Es-tu allé au\nMUSEE?",
  ["_PewterCitySuperNerd1ItsRightHereText"] = "C'est par là!\nL'entrée est\011payante mais ça\011vaut l'coup!",
  ["_PewterCitySuperNerd1WerentThoseFossilsAmazingText"] = "Les fossiles du\nMONT SELENITE\011sont beaux, hein?",
  ["_PewterCitySuperNerd1YouHaveToGoText"] = "Non?\nMais il faut y\011aller, voyons!",
  ["_PewterCitySuperNerd2DoYouKnowWhatImDoingText"] = "Psssst!\nTu sais c'que\011j'fais?",
  ["_PewterCitySuperNerd2ImSprayingRepelText"] = "Je vaporise du\nREPOUSSE pour\011éloigner les\011POKéMON de mon\011bô jardin!",
  ["_PewterCitySuperNerd2ThatsRightText"] = "Ah bon?\nOK.",
  ["_PewterCityTrainerTipsText"] = "ASTUCE\012Chaque POKéMON\nprenant part au\011combat, même pen-\011dant une seconde,\011gagne de l'EXP!",
  ["_PewterCityYoungsterGoTakeOnBrockText"] = "Si t'es fort...\nT'as pas tort...\011Alors...\011Bats PIERRE...\011Ou t'es mort!",
  ["_PewterCityYoungsterYoureATrainerFollowMeText"] = "T'es un dresseur?\nPIERRE cherche un\011adversaire!\011Suis-moi!",
  ["_PewterGymBrockBoulderBadgeInfoText"] = "\012C'est un BADGE\nofficiel de la\011LIGUE POKéMON!\012Les POKéMON de\nson détenteur\011deviennent plus\011puissants!\012La technique\nFLASH peut être\011utilisée!",
  ["_PewterGymBrockPostBattleAdviceText"] = "Il y a plusieurs\ntypes de\011dresseurs dans le\011monde!\012Tu sembles être\nun dresseur\011d'exception!\012Va à l'ARENE\nd'AZURIA pour\011tester tes\011capacités.",
  ["_PewterGymBrockPreBattleText"] = "Je suis PIERRE!\nJe suis le\011CHAMPION\011d'ARGENTA!\012Je crois en la\ngrande résistance\011de la pierre!\012C'est pourquoi\nmes POKéMON sont\011des élémentaires\011de pierre!\012Tu veux toujours\nte battre avec\011moi? Très bien.\011En garde!",
  ["_PewterGymBrockReceivedBoulderBadgeText"] = "Hmm...\nBeau combat.\012En reconnaissance\nde ta victoire,\011voici le BADGE\011ROCHE!\012{PLAYER} reçoit\nle BADGE ROCHE!",
  ["_PewterGymBrockWaitTakeThisText"] = "Attends! Prends\nça avec toi!",
  ["_PewterGymCooltrainerMAfterBattleText"] = "Tu es fort...\nMais pas autant\011que PIERRE!",
  ["_PewterGymCooltrainerMBattleText"] = "Une minute,\ngamin!\012Tu es encore loin\nde PIERRE, tu\011vas devoir\011m'affronter!",
  ["_PewterGymCooltrainerMEndBattleText"] = "Zut!\012J'aurais dû te\nlaisser passer!",
  ["_PewterGymGuideAdviceText"] = "Le 1er POKéMON\napparaissant dans\011un combat est\011celui en tête de\011la LISTE POKéMON!\012En changeant\nl'ordre des\011POKéMON, tu\011peux changer de\011stratégie!",
  ["_PewterGymGuideBeginAdviceText"] = "OK! C'est\nparti!",
  ["_PewterGymGuideFreeServiceText"] = "C'est gratuit,\nprofites-en! ",
  ["_PewterGymGuidePostBattleText"] = "Je le savais!\nTu as l'âme d'un\011champion!",
  ["_PewterGymGuidePreAdviceText"] = "Salut graine de\nCHAMPION!\012Je ne suis pas\ndresseur mais mes\011conseils sont\011avisés!\012Laisse-moi te\nmener à la\011victoire!",
  ["_PewterGymReceivedTM34Text"] = "{PLAYER} reçoit\nla CT34!",
  ["_PewterGymTM34NoRoomText"] = "Votre inventaire\nest plein!",
  ["_PewterMartSuperNerdText"] = "Si tu élèves bien\ntes POKéMON, même\011les plus faibles,\011il se passera\011rien que des\011bonnes choses!",
  ["_PewterMartYoungsterText"] = "Un vieil homme\nm'a vendu cet\011étrange poisson\011POKéMON!\012Il est super nul\net il m'a coûté\011500¥!",
  ["_PewterNidoranHouseLittleBoyText"] = "NIDORAN, assis!",
  ["_PewterNidoranHouseMiddleAgedManText"] = "Notre POKéMON est\nun échangé, il\011est difficile à\011maîtriser.\012Un échangé est\nun POKéMON\011échangé avec un\011autre joueur.\012Il grandit vite,\nmais il n'en fait\011qu'à sa tête\011pendant les\011combats!\012Si seulement nous\navions des...\011BADGES!",
  ["_PewterNidoranHouseNidoranText"] = "NIDORAN: Nidoni!",
  ["_PewterPokecenterGentlemanText"] = "Quoi!?\012La TEAM ROCKET\na investi le\011MONT SELENITE!\012Damnation!",
  ["_PewterPokecenterJigglypuffText"] = "RONDOUDOU: Dou!\nDoudouuuu!",
  ["_PewterSpeechHouseGamblerText"] = "Un POKéMON\napprend des\011attaques en\011gagnant des\011niveaux!\012Mais certaines\nattaques ne\011sont enseignées\011que par les\011dresseurs!",
  ["_PewterSpeechHouseYoungsterText"] = "Les POKéMON sont\nplus faciles à\011capturer une fois\011endormis ou\011blessés!\012Mais attraper un\nPOKéMON, c'est\011jamais du tout\011cuit!",
  ["_PickUpPayDayMoneyText"] = "{PLAYER} ramasse:\n¥{NUM:wTotalPayDayMoney, 3 | LEADING_ZEROES | LEFT_ALIGN}!",
  ["_PidgeotDexEntry"] = "Il chasse en\nsurvolant la\nsurface de l'eau\012et en plongeant\npour attraper des\nproies faciles.",
  ["_PidgeottoDexEntry"] = "Il protège son\nterritoire avec\nardeur et\012repousse à coups\nde bec tout\nintrus.",
