  ["_PokemonTower4FChanneler2AfterBattleText"] = "Nous ne pouvons\nidentifier les\011SPECTRES.",
  ["_PokemonTower4FChanneler2BattleText"] = "Sois maudit!!!!\nKwaaah!",
  ["_PokemonTower4FChanneler2EndBattleText"] = "QUOI!",
  ["_PokemonTower4FChanneler3AfterBattleText"] = "Que les âmes des\ndéfunts POKéMON\011reposent en paix!",
