  ["_Route15SignText"] = "ROUTE 15\nPARMANIE\011à l'Ouest",
  ["_Route15UpstairsBinocularsText"] = "Vous regardez\ndans les\011jumelles...\012Un grand et bel\noiseau vole vers\011la mer.",
