  ["_Route22Rival1DefeatedText"] = "Haha!\nTu as eu une\011chance de\011minable, minable!",
  ["_Route22Rival1VictoryText"] = "{RIVAL}: Quoi?\nPourquoi j'ai 2\011POKéMON?\012Tu devrais\011aussi en choper\011d'autres,\011minable!",
  ["_Route22Rival2DefeatedText"] = "Quoi!?\012Je pensais à\nautre chose!",
  ["_Route22Rival2VictoryText"] = "{RIVAL}: Hahaha!\n{PLAYER}! T'es\011vraiment nul! Un\011énorme minable,\011pas bon du tout!\012Allez, retourne\nt'entraîner!",
  ["_Route22RivalAfterBattleText1"] = "Y paraît qu'il y\na des dresseurs\011balèzes dans la\011LIGUE POKéMON!\012Je dois trouver\nun moyen de les\011battre!\012Tu devrais t'y\nmettre aussi,\011minable!",
  ["_Route22RivalAfterBattleText2"] = "Tu m'as amusé\nun peu! J'suis\011chaud pour la\011LIGUE POKéMON!\012{PLAYER}, t'es\nvraiment un\011minable!\012Mais je crois que\ntu commences à le\011savoir, minable!",
  ["_Route22RivalBeforeBattleText1"] = "{RIVAL}: Hé!\n{PLAYER}!\012Tu vas à la\nLIGUE POKéMON?\012Laisse tomber!\nT'es bien trop\011minable. En plus\011il te faut des\011BADGES!\012Les gardes ne\nlaisseront pas\011passer un minable\011comme toi!\012Enfin, si tu veux\nje suis prêt à\011exploser tes\011POKéMON!",
  ["_Route22RivalBeforeBattleText2"] = "{RIVAL}: Tiens?\n{PLAYER}! Quelle\011bonne surprise,\011tu es là aussi?!\012Alors comme ça on\nva à la LIGUE?\012Tu as tous les\nBADGES aussi?\011C'est bien!\012Eh ben...j'vais\nt'casser en deux\011minab'.\011Ta maman te\011reconnaîtra qu'à\011la couleur de ton\011p'tit cartable!\012Allez, viens\nprendre ta baffe,\011minable!",
  ["_Route23GoRightAheadText"] = "\012OK! Tu peux\npasser!",
  ["_Route23OhThatIsTheBadgeText"] = "On ne passe que\nsur présentation\011d'un...\011{RAM:wNameBuffer}!\012Oh! Mais c'est le\n{RAM:wNameBuffer}!",
  ["_Route23VictoryRoadGateSignText"] = "ROUTE VICTOIRE\n- LIGUE POKéMON",
  ["_Route23YouDontHaveTheBadgeYetText"] = "On ne passe que\nsur présentation\011d'un...\011{RAM:wNameBuffer}!\012Tu n'as pas le\n{RAM:wNameBuffer}!\012Il te le faut\npour accéder à la\011LIGUE POKéMON!",
  ["_Route24CooltrainerF1AfterBattleText"] = "J'ai participé,\net j'ai perdu!",
  ["_Route24CooltrainerF1BattleText"] = "Je suis la 4ème!\nT'en veux encore?",
  ["_Route24CooltrainerF1EndBattleText"] = "Tu...\n...m'as battue!",
  ["_Route24CooltrainerF2AfterBattleText"] = "J'ai fait de mon\nmieux!",
  ["_Route24CooltrainerF2BattleText"] = "Je suis la 2ème!\nCa rigole plus!",
  ["_Route24CooltrainerF2EndBattleText"] = "Ben...\nTu m'as battue?",
  ["_Route24CooltrainerM1DefeatedText"] = "Arrgh!\nTu es très fort!",
  ["_Route24CooltrainerM1JoinTeamRocketText"] = "Veux-tu rejoindre\nles rangs de la\011TEAM ROCKET?\012Nous sommes des\ndresseurs de\011POKéMON très\011méchants!\012Ca t'intéresse?\012T'es sûr?\012Allez, viens!\012Bon, je t'ai dit\nde venir avec\011nous!\012Je vois...\012Je vais me\nmontrer plus\011persuasif!",
  ["_Route24CooltrainerM1NoRoomText"] = "Votre inventaire\nest plein!",
  ["_Route24CooltrainerM1ReceivedNuggetText"] = "{PLAYER} obtient:\n{RAM:wStringBuffer}!",
  ["_Route24CooltrainerM1YouBeatOurContestText"] = "Félicitations!\nTu as battu les\0115 dresseurs!",
  ["_Route24CooltrainerM1YouCouldBecomeATopLeaderText"] = "Tu pourrais vite\ndevenir un chef\011au sein de la\011TEAM ROCKET!",
  ["_Route24CooltrainerM1YouJustEarnedAPrizeText"] = "\012Tu as gagné un\nfabuleux prix!",
  ["_Route24CooltrainerM2AfterBattleText"] = "Je me cache, les\ngens sur le pont\011me font peur!",
  ["_Route24CooltrainerM2BattleText"] = "Je t'ai vu!",
  ["_Route24CooltrainerM2EndBattleText"] = "Oh!\nJ'ai vu ma\011défaite!",
  ["_Route24CooltrainerM3AfterBattleText"] = "Pas de regrets,\nj'ai fait de mon\011mieux!",
  ["_Route24CooltrainerM3BattleText"] = "OK! J'suis le 5!\nJ'vais te broyer!",
  ["_Route24CooltrainerM3EndBattleText"] = "Ah!\nPurée!",
  ["_Route24Youngster1AfterBattleText"] = "J'ai fait de mon\nmieux!",
  ["_Route24Youngster1BattleText"] = "Je suis le 3ème!\nC'est pas gagné!",
  ["_Route24Youngster1EndBattleText"] = "Oh!\nTu m'as écrasé!",
  ["_Route24Youngster2AfterBattleText"] = "J'ai fait de mon\nmieux. Si si!\011C'est vrai!",
  ["_Route24Youngster2BattleText"] = "Voici le PONT\nPEPITE!\0115 dresseurs\011défendent ce\011pont! Bats-nous\011et tu seras\011super content!\012Tu crois pouvoir\ny arriver?",
  ["_Route24Youngster2EndBattleText"] = "Haha!\nBien joué!",
  ["_Route25BillSignText"] = "VILLA\nLEO habite ici!",
  ["_Route25CooltrainerF1AfterBattleText"] = "Mon mec à moi, il\nest très fort!",
  ["_Route25CooltrainerF1BattleText"] = "Mon p'tit copain,\nc'est le plus\011beau de tous!\011J'ai le plus beau\011de tous les\011copains du monde!",
  ["_Route25CooltrainerF1EndBattleText"] = "Hmm...\nJ'pensais à mon\011mec!",
  ["_Route25CooltrainerF2AfterBattleText"] = "Tu viens du MONT\nSELENITE? Tu as\011un MELOFEE?",
  ["_Route25CooltrainerF2BattleText"] = "Mon copain a des\nPOKéMON trognons!\011Je suis jalouse!",
  ["_Route25CooltrainerF2EndBattleText"] = "J'suis\npas jalouse,\011j'suis nulle!",
  ["_Route25CooltrainerMAfterBattleText"] = "Ma copine va\nm'encourager.",
  ["_Route25CooltrainerMBattleText"] = "J'suis cool.\nEt j'ai une\011copine aussi!",
  ["_Route25CooltrainerMEndBattleText"] = "Zut!\nZut, zut et zut!",
  ["_Route25Hiker1AfterBattleText"] = "Aaaaaaargh!\nJe me suis fait\011mordre par un\011NOSFERAPTI.",
  ["_Route25Hiker1BattleText"] = "J'arrive du MONT\nSELENITE, et je\011suis prêt!",
  ["_Route25Hiker1EndBattleText"] = "Pfiou!\nT'es un balèze!",
  ["_Route25Hiker2AfterBattleText"] = "Le collectionneur\na plein de\011POKéMON rares.",
  ["_Route25Hiker2BattleText"] = "Je cherche le\ncollectionneur de\011POKéMON!",
  ["_Route25Hiker2EndBattleText"] = "Heu!\nJ'suis eu.",
  ["_Route25Hiker3AfterBattleText"] = "La route, en bas,\nest un raccourci\011vers AZURIA.",
  ["_Route25Hiker3BattleText"] = "Tu vas voir LEO?\nOk, mais d'abord,\011BASTOONNN!",
  ["_Route25Hiker3EndBattleText"] = "Hmm.\nTu te bats bien.",
  ["_Route25Youngster1AfterBattleText"] = "Chaque POKéMON a\nses faiblesses.\011Il vaut mieux te\011faire une équipe\011avec des POKéMON\011variés.",
  ["_Route25Youngster1BattleText"] = "Les dresseurs\nviennent ici pour\011s'entraîner!",
  ["_Route25Youngster1EndBattleText"] = "Tu es\nbon gagnant.",
  ["_Route25Youngster2AfterBattleText"] = "Sur L'OCEANE,\nj'ai vu des\011dresseurs du\011monde entier.",
  ["_Route25Youngster2BattleText"] = "Je suis allé à\nune super fête.\011C'était sur\011L'OCEANE, à\011CARMIN SUR MER!",
  ["_Route25Youngster2EndBattleText"] = "Yaha!\nJ'suis pas fou!",
  ["_Route25Youngster3AfterBattleText"] = "Si ton POKéMON\nest devenu fou ou\011s'est endormi,\011rappelle-le!",
  ["_Route25Youngster3BattleText"] = "Y'a un dresseur\nde trop ici!",
  ["_Route25Youngster3EndBattleText"] = "Ben...\nJ'suis d'trop!",
  ["_Route2DiglettsCaveSignText"] = "CAVE TAUPIQUEUR",
  ["_Route2GateOaksAideFlashExplanationText"] = "La CS du FLASH\npeut éclairer les\011endroits sombres.",
  ["_Route2GateYoungsterText"] = "Si un POKéMON a\nappris le FLASH,\011tu pourras tra-\011verser la GROTTE.",
  ["_Route2SignText"] = "ROUTE 2\nJADIELLE -\011ARGENTA",
  ["_Route2TradeHouseScientistText"] = "Un POKéMON K.O.\nne peut se battre\011mais il peut\011encore utiliser\011des techniques\011comme la COUPE!",
  ["_Route3CooltrainerF1AfterBattleText"] = "Baisse les yeux\nsi tu veux éviter\011la baston!",
  ["_Route3CooltrainerF1BattleText"] = "Tu veux ma\nphoto?",
  ["_Route3CooltrainerF1EndBattleText"] = "Tiens,\nc'est ma photo!",
  ["_Route3CooltrainerF2AfterBattleText"] = "Evite les regards\nsi tu ne veux\011pas combattre!",
  ["_Route3CooltrainerF2BattleText"] = "Dis donc beau\nténébreux...\011Tu veux qu'on\011s'boxe?",
  ["_Route3CooltrainerF2EndBattleText"] = "Hmmm...\nSois gentil!",
  ["_Route3CooltrainerF3AfterBattleText"] = "La ROUTE 4\nest au pied du\011MONT SELENITE.",
  ["_Route3CooltrainerF3BattleText"] = "Hé! Tu m'as\ntouchée là?",
  ["_Route3CooltrainerF3EndBattleText"] = "OK!",
  ["_Route3SignText"] = "ROUTE 3 vers le\nMONT SELENITE",
  ["_Route3Text1"] = "Pfou...Je vais\nfaire une halte.\011Moouarf...\012Ce tunnel\nd'AZURIA est\011épuisant!",
  ["_Route3Youngster1AfterBattleText"] = "Il y a beaucoup\nde POKéMON\011différents dans\011la forêt!",
  ["_Route3Youngster1BattleText"] = "Hé! On s'est déjà\nvu dans la FORET\011DE JADE!",
  ["_Route3Youngster1EndBattleText"] = "Ben,\ntu m'as encore\011battu!",
  ["_Route3Youngster2AfterBattleText"] = "Pour ranger tes\nPOKéMON,\011utilise un PC.\011Chaque boîte\011contient\01120 POKéMON!",
  ["_Route3Youngster2BattleText"] = "Yahaa! J'adore\nles shorts! Viens\011t'battre!",
  ["_Route3Youngster2EndBattleText"] = "Nyahaa,\ntu m'as taillé\011un short!",
  ["_Route3Youngster3AfterBattleText"] = "Quand l'une des\nboîtes de ton PC\011est pleine,\011active une autre\011boîte!",
  ["_Route3Youngster3BattleText"] = "T'es un dresseur?\nA l'attaque!",
  ["_Route3Youngster3EndBattleText"] = "Avec\nd'autres POKéMON\011j'aurais gagné!",
  ["_Route3Youngster4AfterBattleText"] = "Je porte toujours\ndes shorts, même\011en hiver!",
  ["_Route3Youngster4BattleText"] = "Hé! T'as pas de\nshort! T'es nul!",
  ["_Route3Youngster4EndBattleText"] = "Perdu!\nPerdu, et perdu!",
  ["_Route3Youngster5AfterBattleText"] = "Les POKéMON\ndomptés sont plus\011forts que\011les sauvages!",
  ["_Route3Youngster5BattleText"] = "Fais gaffe à mes\nnouveaux POKéMON!",
  ["_Route3Youngster5EndBattleText"] = "Ben,\ny m'en faut\011des nouveaux!",
  ["_Route4CooltrainerF1Text"] = "Ha! J'ai trébuché\nsur un POKéMON de\011pierre: RACAILLOU!",
  ["_Route4CooltrainerF2AfterBattleText"] = "Je crois qu'il\nn'y a plus de\011champignons dans\011le coin.\012Je les ai tous\nramassés.",
  ["_Route4CooltrainerF2BattleText"] = "Je viens chercher\nmon POKéMON\011champignon!",
  ["_Route4CooltrainerF2EndBattleText"] = "Oh!\nMon POKéMON!",
  ["_Route4MtMoonSignText"] = "MONT SELENITE\nEntrée du tunnel",
  ["_Route4SignText"] = "ROUTE 4\nMONT SELENITE -\011AZURIA",
  ["_Route5UndergroundPathSignText"] = "SOUTERRAIN\nAZURIA -\011CARMIN SUR MER",
  ["_Route6CooltrainerAfterBattleText"] = "Soupirs...\nGros soupirs...",
  ["_Route6CooltrainerF1BattleText"] = "Heu, c'est une\nconversation\011privée, DEGAGE!",
  ["_Route6CooltrainerF1EndBattleText"] = "Non!\nPas bon perdre!",
  ["_Route6CooltrainerF2AfterBattleText"] = "Je veux être\nforte! Comme toi!\011C'est quoi ton\011secret?",
  ["_Route6CooltrainerF2BattleText"] = "Qui ça? Moi?\nOk. Attaque!",
  ["_Route6CooltrainerF2EndBattleText"] = "Ho.\nPas glop!",
  ["_Route6CooltrainerM1BattleText"] = "Qui est là?\nArrête de nous\011espionner!",
  ["_Route6CooltrainerM1EndBattleText"] = "...\nJ'suis nul!",
  ["_Route6CooltrainerM2AfterBattleText"] = "Il me faut plus\nde POKéMON\011pour me protéger.",
  ["_Route6CooltrainerM2BattleText"] = "Hein? Tu veux\nme causer?",
  ["_Route6CooltrainerM2EndBattleText"] = "...\nJ'ai rien fait!",
  ["_Route6UndergroundPathSignText"] = "SOUTERRAIN\nAZURIA -\011CARMIN SUR MER",
  ["_Route6Youngster1AfterBattleText"] = "Les insectes\nj'aime ça, je\011retourne dans la\011FORET DE JADE.",
  ["_Route6Youngster1BattleText"] = "C'est plein\nd'insectes, ici.",
  ["_Route6Youngster1EndBattleText"] = "Non!\nC'est une blague!",
  ["_Route6Youngster2AfterBattleText"] = "Mes POKéMON sont\nnuls ou je suis\011très mauvais?",
  ["_Route6Youngster2BattleText"] = "J't'ai jamais\nvu dans le coin!\011T'es puissant?",
  ["_Route6Youngster2EndBattleText"] = "Whaa!\nTrop puissant!",
  ["_Route7UndergroundPathSignText"] = "SOUTERRAIN\nCELADOPOLE -\011LAVANVILLE",
  ["_Route8CooltrainerF1AfterBattleText"] = "Quand un POKéMON\ngrandit, il est\011gros et moche.\011Je les préfère\011tout petits!",
  ["_Route8CooltrainerF1BattleText"] = "Moi, j'aime les\nNIDORAN! Yaha!",
  ["_Route8CooltrainerF1EndBattleText"] = "Hein?",
  ["_Route8CooltrainerF2AfterBattleText"] = "Je trouve que\nROUCOOL et\011RATTATA sont trop\011cool!",
  ["_Route8CooltrainerF2BattleText"] = "MIAOUSS est si\nmignon. Miaou!",
  ["_Route8CooltrainerF2EndBattleText"] = "Miaou!",
  ["_Route8CooltrainerF3AfterBattleText"] = "Le gardien de la\nporte de SAFRANIA\011ne nous laissera\011pas passer!",
  ["_Route8CooltrainerF3BattleText"] = "Je sais, on a\nl'air idiot\011debout!",
  ["_Route8CooltrainerF3EndBattleText"] = "Ben...\nC'est malin ça!",
  ["_Route8CooltrainerF4AfterBattleText"] = "Il paraît que\nMELOFEE peut\011évoluer grâce à \011une PIERRE LUNE.",
  ["_Route8CooltrainerF4BattleText"] = "Qu'il est mimi,\ngentil et trognon\011ce POKéMON!\011Il est à qui?\011Hein? A qui?",
  ["_Route8CooltrainerF4EndBattleText"] = "Arrête!\012T'es pas gentil\navec MELOFEE!",
  ["_Route8Gambler1AfterBattleText"] = "Dame chance n'est\npas avec moi!",
  ["_Route8Gambler1BattleText"] = "Le sort en est\njeté!",
  ["_Route8Gambler1EndBattleText"] = "Haaa!\nLe hasard...",
  ["_Route8Gambler2AfterBattleText"] = "Le jeu et les\nPOKéMON, c'est\011comme les\011cacahuètes.\011Tu commences et\011tu peux plus\011t'arrêter! Fou!",
  ["_Route8Gambler2BattleText"] = "Je suis un\njoueur errant!",
  ["_Route8Gambler2EndBattleText"] = "J'ai\nraté le jackpot!",
  ["_Route8SuperNerd1AfterBattleText"] = "Je suis meilleur\nà l'école!",
  ["_Route8SuperNerd1BattleText"] = "T'es un bon avec\ntes POKéMON.\011Mais les maths,\011tu connais?",
  ["_Route8SuperNerd1EndBattleText"] = "Ouch!\n2 plus 2... 7?",
  ["_Route8SuperNerd2AfterBattleText"] = "D'abord TADMORV\net après...\011Et puis...",
  ["_Route8SuperNerd2BattleText"] = "Il te faut une\nbonne stratégie!",
  ["_Route8SuperNerd2EndBattleText"] = "Hé!\nPas logique!",
  ["_Route8SuperNerd3AfterBattleText"] = "On est bloqué\nici, aux portes\011de SAFRANIA.",
  ["_Route8SuperNerd3BattleText"] = "L'école c'est\ncool, les POKéMON\011c'est mieux!",
  ["_Route8SuperNerd3EndBattleText"] = "Ben...\nL'école c'est\011plus facile!",
  ["_Route8UndergroundSignText"] = "SOUTERRAIN\nCELADOPOLE -\011LAVANVILLE",
  ["_Route9CooltrainerF1AfterBattleText"] = "Il te faudra de\nla lumière dans\011ce sombre tunnel.",
  ["_Route9CooltrainerF1BattleText"] = "T'as des POKéMON\navec toi!\011En garde!",
  ["_Route9CooltrainerF1EndBattleText"] = "Ah!\nBien défendu!",
  ["_Route9CooltrainerF2AfterBattleText"] = "T'as l'air doué!\nBonne chance,\011garçon!",
  ["_Route9CooltrainerF2BattleText"] = "Traite-moi avec\nrespect!",
  ["_Route9CooltrainerF2EndBattleText"] = "...\nJe ne mérite que\011ton dédain!",
  ["_Route9CooltrainerM1AfterBattleText"] = "Passe ton chemin!",
  ["_Route9CooltrainerM1BattleText"] = "Mais qui voilà,\nles bras chargés\011de POKéMON?",
  ["_Route9CooltrainerM1EndBattleText"] = "Paf!\nJ'suis fini!",
  ["_Route9CooltrainerM2AfterBattleText"] = "Tu vas dans la\nGROTTE, toi\011aussi?",
  ["_Route9CooltrainerM2BattleText"] = "Je passe par la\nGROTTE pour voir\011LAVANVILLE!",
  ["_Route9CooltrainerM2EndBattleText"] = "...\nJ'suis pas bon!",
  ["_Route9Hiker1AfterBattleText"] = "T'es un\ncourageux toi!",
  ["_Route9Hiker1BattleText"] = "Bwahaha!\nAllez... \011Viens manger ta\011pâtée...",
  ["_Route9Hiker1EndBattleText"] = "Ha!\nViens, viens!\012Heu, j'ai plus\nde POKéMON!",
  ["_Route9Hiker2AfterBattleText"] = "Les gosses, c'est\npas assez fort!",
  ["_Route9Hiker2BattleText"] = "Hahaha!\nT'es un p'tit\011dur, toi!",
  ["_Route9Hiker2EndBattleText"] = "Dur,\ntrès dur!",
  ["_Route9Hiker3AfterBattleText"] = "Hahahaha!\nQuand j'perds,\011j'me marre!",
  ["_Route9Hiker3BattleText"] = "Viens t'battre,\ngalopin!",
  ["_Route9Hiker3EndBattleText"] = "Ha!\nTu m'as bien eu!",
  ["_Route9SignText"] = "ROUTE 9\nAZURIA-\011GROTTE",
  ["_Route9Youngster1AfterBattleText"] = "Il me faut autre\nchose que des\011insectes pour\011être plus fort...",
  ["_Route9Youngster1BattleText"] = "Mes cocons de\nPOKéMON me\011prennent beaucoup\011de temps!",
  ["_Route9Youngster1EndBattleText"] = "Nyargh?\012Quelle perte de\ntemps!",
  ["_Route9Youngster2AfterBattleText"] = "T'aimes pas les\ninsectes POKéMON?\011T'es infect!",
  ["_Route9Youngster2BattleText"] = "Super-cafards,\nen avant!",
  ["_Route9Youngster2EndBattleText"] = "Super-\ncafards! Houhou!\011Réveillez-vous!",
  ["_SSAnne1FRoomsCooltrainerFAfterBattleText"] = "Tu as fait mal\nà mes POKéMON!\012Il faut que\ntu les soignes\011dans un\011CENTRE POKéMON!!!",
  ["_SSAnne1FRoomsCooltrainerFBattleText"] = "J'ai déniché\nces POKéMON\011un peu partout\011dans le monde!",
  ["_SSAnne1FRoomsCooltrainerFEndBattleText"] = "Quoi!\nUn tour du monde\011pour ce résultat!\011C'est nul!",
  ["_SSAnne1FRoomsGentleman1AfterBattleText"] = "Il faut être\ngentil avec ses\011POKéMON!",
  ["_SSAnne1FRoomsGentleman1BattleText"] = "Je voyage\ntoujours en\011solitaire!\012Mes POKéMON\nsont mes amis!",
  ["_SSAnne1FRoomsGentleman1EndBattleText"] = "Non!\nMes p'tits amis!",
  ["_SSAnne1FRoomsGentleman2AfterBattleText"] = "J'aimerais être\nseul! Va-t'en!",
  ["_SSAnne1FRoomsGentleman2BattleText"] = "Toi, jeune sot! Tu\noses entrer ici!?",
  ["_SSAnne1FRoomsGentleman2EndBattleText"] = "Huf!\nTu es mal élevé!!",
  ["_SSAnne1FRoomsGentleman3Text"] = "Pst! Je suis de\nl'INTERPOLICE!\012Je suis sur la\ntrace de la\011TEAM ROCKET!\011Chut!",
  ["_SSAnne1FRoomsGirl1Text"] = "Serveur,\namenez-moi une\011tarte aux poires!",
  ["_SSAnne1FRoomsGirl2Text"] = "Nous parcourons\nles mers du\011monde entier!",
  ["_SSAnne1FRoomsLittleGirlText"] = "Je voyage\ntoujours avec\011GRODOUDOU!",
  ["_SSAnne1FRoomsMiddleAgedManText"] = "Ha! Une croisière!\nC'est tellement\011romantique!",
  ["_SSAnne1FRoomsWigglytuffText"] = "GRODOUDOU: Gro!\nDouuuuuuu!",
  ["_SSAnne1FRoomsYoungsterAfterBattleText"] = "Soyons amis,\nOK?\012On pourra alors\néchanger nos\011POKéMON!",
  ["_SSAnne1FRoomsYoungsterBattleText"] = "J'aime les\nPOKéMON! Et toi?",
  ["_SSAnne1FRoomsYoungsterEndBattleText"] = "Woo!\nT'es cool, toi!",
  ["_SSAnne1FSailorText"] = "Les passagers\nsont en\011ébullition!\012Ils vont\ncertainement vous\011provoquer en\011duel!",
  ["_SSAnne1FWaiterText"] = "Bonjour! Je suis\nle serveur de ce\011bateau!\012Je me ferai une\njoie de vous\011servir!\012Ha! L'air du\ngrand large!",
  ["_SSAnne2FRivalCutMasterText"] = "{RIVAL}: Il y\na le maître de la\011technique COUPE\011à bord.\012Mais ce n'est\nqu'un vieil homme\011malade et sénile!\012La technique\nCOUPE est très\011utile!\012Tu devrais le\nrencontrer!\011Salut! Minable!",
  ["_SSAnne2FRivalDefeatedText"] = "Mouaff!\012Au moins, tu\nt'occupes de tes\011POKéMON!",
  ["_SSAnne2FRivalText"] = "{RIVAL}: Salut!\n{PLAYER}!\012Toi! Ici!\nSans blague!\012{PLAYER}, as-tu\nvraiment été\011invité?\012Où en es-tu avec\nton POKéDEX?\012Moi, j'ai déjà\nattrapé 40\011POKéMON! Minable!\012Y'en a partout!\012Tu n'as qu'à ramper\ndans les hautes\011herbes!",
  ["_SSAnne2FRivalVictoryText"] = "{PLAYER}! Tu as\nle mal de mer?\012Tu devrais te\nmettre au frais!\011Minable!",
  ["_SSAnne2FRoomsBeautyText"] = "C'est assez\nfréquent d'avoir\011le mal de mer!",
  ["_SSAnne2FRoomsBrunetteGirlText"] = "Le CAPITAINE\navait l'air tout\011pâlot!",
  ["_SSAnne2FRoomsCooltrainerFAfterBattleText"] = "Woah! Tes POKéMON\nsont super forts!\011Je les adore!",
  ["_SSAnne2FRoomsCooltrainerFBattleText"] = "Je ne t'ai pas vu\nà la fête.",
  ["_SSAnne2FRoomsCooltrainerFEndBattleText"] = "Relax!\nT'énerve pas!!!",
  ["_SSAnne2FRoomsFisherAfterBattleText"] = "Une fête?\012Elle doit être\nfinie maintenant.",
  ["_SSAnne2FRoomsFisherBattleText"] = "Hé! Regarde ce\nque j'ai pêché!",
  ["_SSAnne2FRoomsFisherEndBattleText"] = "OK!\nJ'suis fait!!",
  ["_SSAnne2FRoomsGentleman1AfterBattleText"] = "Hmm! Il y a 15\nans, j'aurais\011gagné...",
  ["_SSAnne2FRoomsGentleman1BattleText"] = "Les duels contre\nles jeunes me\011maintiennent en\011forme!",
  ["_SSAnne2FRoomsGentleman1EndBattleText"] = "Woah!\nHa! Je me sens\011en pleine forme!",
  ["_SSAnne2FRoomsGentleman2AfterBattleText"] = "Je préfère les\nPOKéMON rares\011et costauds!",
  ["_SSAnne2FRoomsGentleman2BattleText"] = "Que veux-tu?\nUn POKéMON\011costaud ou rare?",
  ["_SSAnne2FRoomsGentleman2EndBattleText"] = "Bravo!\nTu es très fort!",
  ["_SSAnne2FRoomsGentleman3Text"] = "Dans tous mes\nvoyages, je n'ai\011jamais vu un\011POKéMON dormir\011autant!\012Il était un\npeu comme ça...",
  ["_SSAnne2FRoomsGentleman4Text"] = "Oui! J'ai vu des\ngens transporter\011des POKéMON par-\011delà les eaux!",
  ["_SSAnne2FRoomsGentleman5Text"] = "As-tu déjà vu\nle PARC SAFARI\011à PARMANIE?\012On y trouve plein\nde POKéMON rares!",
  ["_SSAnne2FRoomsGrampsText"] = "Les POKéMON\npeuvent couper des\011petits buissons\011avec la technique\011COUPE.",
  ["_SSAnne2FRoomsLittleBoyText"] = "Mon Pôpa et moi,\non pense que le\011PARC SAFARI\011il est génial!",
  ["_SSAnne2FWaiterText"] = "Ce luxueux bateau\naccueille tous\011les dresseurs!\012Dans chaque port\nnous organisons\011une fête pour\011les dresseurs!",
  ["_SSAnne3FSailorText"] = "Notre CAPITAINE\nest un maître\011d'armes!\012Il enseigne\nà ses POKéMON\011la technique\011COUPE!",
  ["_SSAnneB1FRoomsFisherAfterBattleText"] = "J'allais faire de\ntoi mon\011assistant!",
  ["_SSAnneB1FRoomsFisherBattleText"] = "Salut étranger!\nParlons un peu!\012Tous mes POKéMON\nsont aquatiques!",
  ["_SSAnneB1FRoomsFisherEndBattleText"] = "Zut!\nCelui-là s'est\011échappé!",
  ["_SSAnneB1FRoomsMachokeText"] = "MACHOPEUR: Chop!\nChop! Chop!",
  ["_SSAnneB1FRoomsSailor1AfterBattleText"] = "Alors, mousse, tu\nveux devenir\011un marin?",
  ["_SSAnneB1FRoomsSailor1BattleText"] = "Tu sais ce que\nl'on raconte sur\011les marins et\011les duels!",
  ["_SSAnneB1FRoomsSailor1EndBattleText"] = "Ouaip!\nBeau combat!",
  ["_SSAnneB1FRoomsSailor2AfterBattleText"] = "As-tu rencontré le\nMaître Pêcheur à\011CARMIN?",
  ["_SSAnneB1FRoomsSailor2BattleText"] = "Ma réputation de\nmarin est en jeu!",
  ["_SSAnneB1FRoomsSailor2EndBattleText"] = "Ha!\nJe sombre!",
  ["_SSAnneB1FRoomsSailor3AfterBattleText"] = "Tous nos POKéMON\nviennent des\011hautes mers!",
  ["_SSAnneB1FRoomsSailor3BattleText"] = "Nous, les marins,\non a aussi des\011POKéMON!",
  ["_SSAnneB1FRoomsSailor3EndBattleText"] = "OK!\nT'es pas nul!",
  ["_SSAnneB1FRoomsSailor4AfterBattleText"] = "Les POKéMON d'eau\nvivent dans les\011grands fonds!\012J'ai besoin d'une\nCANNE!",
  ["_SSAnneB1FRoomsSailor4BattleText"] = "J'aime les p'tits\ngars joyeux\011comme toi!",
  ["_SSAnneB1FRoomsSailor4EndBattleText"] = "Hein!\nJ'ai perdu? Argh!",
  ["_SSAnneB1FRoomsSailor5AfterBattleText"] = "Souvent, quelques\nméduses sont\011entraînées dans\011le sillage\011du bateau...",
  ["_SSAnneB1FRoomsSailor5BattleText"] = "Si tu perds, on\nte balance aux\011requins!",
  ["_SSAnneB1FRoomsSailor5EndBattleText"] = "Hein?\nBattu par toi?",
  ["_SSAnneB1FRoomsSuperNerdText"] = "Mon POKéMON,\nMACHOPEUR, est\011super fort!!!\012Sa FORCE lui\npermet de bouger\011les rochers!",
  ["_SSAnneBowCooltrainerMText"] = "Gueuh! J'suis\nmalaaaaade...\012Je vais bientôt\nvom... (beurp)",
  ["_SSAnneBowSailor1Text"] = "Nyah! Briquer le\npont c'est un\011travail épuisant!",
  ["_SSAnneBowSailor2AfterBattleText"] = "Tu sais combien\nil y a de POKéMON\011différents? Hein,\011tu l'sais, hein?",
  ["_SSAnneBowSailor2BattleText"] = "Hé! Copain!\012Tu danses?\nUn tango?",
  ["_SSAnneBowSailor2EndBattleText"] = "...\nT'es bon!",
  ["_SSAnneBowSailor3AfterBattleText"] = "Mon Pôpa, y dit\nqu'y a 100 POKéMON\011différents. J'suis\011sûr qu'y en a\011plus...",
  ["_SSAnneBowSailor3BattleText"] = "Hoho! Alors, on\na le mal de mer? ",
  ["_SSAnneBowSailor3EndBattleText"] = "Oh!\nBeau combat!",
  ["_SSAnneBowSuperNerdText"] = "La fête est\nfinie! Nous\012allons bientôt\nlever l'ancre!",
  ["_SSAnneCaptainsRoomCaptainHM01NoRoomText"] = "Ha zut! Tu n'as\nplus de place\011pour cet objet!",
  ["_SSAnneCaptainsRoomCaptainIFeelMuchBetterText"] = "CAPITAINE: Merci\nmoussaillon!\011Ca va beaucoup\011mieux...\012Mille sabords!\nTu veux voir\011la technique\011COUPE?\012Je pourrais te la\nmontrer, mais\011j'suis malade.\012Je sais!\nPrends ça!\012C'est la technique\nCOUPE.\011Enseigne-la à\011tes POKéMON!",
  ["_SSAnneCaptainsRoomCaptainNotSickAnymoreText"] = "CAPITAINE: Haaaa!\012Maintenant que\nje suis guéri, on\011va lever l'ancre!",
  ["_SSAnneCaptainsRoomCaptainReceivedHM01Text"] = "{PLAYER} obtient\n{RAM:wStringBuffer}!",
  ["_SSAnneCaptainsRoomRubCaptainsBackText"] = "CAPITAINE: Blorf.\nJ'suis pas bien.\011Beurp...\012{PLAYER} masse\nle dos du\011CAPITAINE!\012Scratch...\nScratch...",
  ["_SSAnneCaptainsRoomSeasickBookText"] = "Comment guérir\nle mal de mer...\011Le CAPITAINE lit\011ce manuel!",
  ["_SSAnneCaptainsRoomTrashText"] = "Quoi?!?\nIl a mangé ça???",
  ["_SSAnneKitchenCook1Text"] = "Hé! Le mouflet,\ny'en a qui bossent\012dur ici!\nAlors dégage!",
  ["_SSAnneKitchenCook2Text"] = "J'ai vu une Ball\nbizarre dans la\011poubelle...",
  ["_SSAnneKitchenCook3Text"] = "J'ai trop de\nboulot! J'en ai\011des vertiges!",
  ["_SSAnneKitchenCook4Text"] = "Pourquoi?\nPourquoi moi?\012J'suis tout\nl'temps d'corvée\011d'patates...",
  ["_SSAnneKitchenCook5Text"] = "Tu connais\nRONFLEX?\012Il passe ses\njournées à manger\011et à pioncer!",
  ["_SSAnneKitchenCook6Text"] = "Sniff... \n...sniff...\012J'épluche\ndes oignons...",
  ["_SSAnneKitchenCook7MainCourseIsText"] = "Hm, hm! Je suis\nle chef cuistot!\012Voilà le menu:",
  ["_SSTicketNoRoomText"] = "Ton inventaire\nest plein, mec!",
  ["_SSTicketReceivedText"] = "{PLAYER} obtient:\n{RAM:wStringBuffer}!",
  ["_SafariZoneAngryText"] = "Le {RAM:wEnemyMonNick}\nsauvage se fâche!",
  ["_SafariZoneCenterRestHouseGirlText"] = "JULIA: Où est\nNICO, mon petit\011ami?",
  ["_SafariZoneCenterRestHouseScientistText"] = "Je capture des\nPOKéMON pour\011les offrir!",
  ["_SafariZoneCenterRestHouseSignText"] = "ABRI",
  ["_SafariZoneCenterTrainerTipsSignText"] = "ASTUCE\012Appuyez sur START\npour consulter la\011montre!",
  ["_SafariZoneEastRestHouseRockerText"] = "J'ai trouvé un\nLEVEINARD!\012J'ai bien fait\nde chercher\011pendant 4 heures!",
  ["_SafariZoneEastRestHouseScientistText"] = "T'en as capturé\ncombien? Moi\011j'suis naze!",
  ["_SafariZoneEastRestHouseSignText"] = "ABRI",
  ["_SafariZoneEastRestHouseSilphWorkerMText"] = "Pffff!\nJ'en ai marre!",
  ["_SafariZoneEastSignText"] = "PARC CENTRAL\nNORD: PARC 2",
  ["_SafariZoneEastTrainerTipsText"] = "ASTUCE\012Le temps s'écoule\nen fonction des\011pas!",
  ["_SafariZoneEatingText"] = "Le {RAM:wEnemyMonNick}\nsauvage mange!",
  ["_SafariZoneGateSafariZoneWorker1CallYouOnThePAText"] = "\012J'utiliserai le\nHAUT-PARLEUR\011lorsque ton temps\011ou tes SAFARI\011BALL seront\011épuisés!",
  ["_SafariZoneGateSafariZoneWorker1GoodHaulComeAgainText"] = "Bonne chasse?\nAllez...\011A plus tard!",
  ["_SafariZoneGateSafariZoneWorker1GoodLuckText"] = "Bonne chance!",
  ["_SafariZoneGateSafariZoneWorker1LeavingEarlyText"] = "On part déjà?",
  ["_SafariZoneGateSafariZoneWorker1NotEnoughMoneyText"] = "Hop hop hop!\nPas d'sous!",
  ["_SafariZoneGateSafariZoneWorker1PleaseComeAgainText"] = "Très bien!\nA plus tard!",
  ["_SafariZoneGateSafariZoneWorker1ReturnSafariBallsText"] = "Donne-moi donc\ntes SAFARI BALL\011neuves.",
  ["_SafariZoneGateSafariZoneWorker1Text"] = "Bienvenue au\nPARC SAFARI!",
  ["_SafariZoneGateSafariZoneWorker1ThatllBe500PleaseText"] = "Ca fera 500¥\nsiouplaît!\012Seul un certain\ntype de POKé BALL\011est utilisé ici.\012{PLAYER} reçoit\n30 SAFARI BALL!",
  ["_SafariZoneGateSafariZoneWorker1WouldYouLikeToJoinText"] = "Pour juste 500¥,\ntu peux attraper\011autant de POKéMON\011qu'il te plaira\011dans le parc!\012Qu'en dis-tu?",
  ["_SafariZoneGateSafariZoneWorker2FirstTimeHereText"] = "C'est...c'est la\npremière fois?",
  ["_SafariZoneGateSafariZoneWorker2SafariZoneExplanationText"] = "Le PARC SAFARI a\n4 zones.\012Tu y trouveras\ndes POKéMON\011différents.\011Utilise tes\011SAFARI BALL pour\011les capturer!\012Le Safari sera\nterminé lorsque\011tu auras épuisé\011tes SAFARI BALL!\012Avant de partir,\nouvre donc une\011nouvelle boîte de\011POKéMON pour\011avoir plus de\011place!",
  ["_SafariZoneGateSafariZoneWorker2YoureARegularHereText"] = "Oh! T'es un\nhabitué!",
  ["_SafariZoneNorthRestHouseGentlemanText"] = "Mon EVOLI s'est\ntransformé en un\011PYROLI!\012Mais celui d'un\nami s'est changé\011en AQUALI!\011Bah pourquoi?",
  ["_SafariZoneNorthRestHouseSafariZoneWorkerText"] = "Un recoin du PARC\nSAFARI renferme\011un prix!",
  ["_SafariZoneNorthRestHouseScientistText"] = "Tu peux garder\ntous les objets\011trouvés dans le\011coin.\012Mais ne perds pas\nde temps à tous\011les essayer!",
  ["_SafariZoneNorthRestHouseSignText"] = "ABRI",
  ["_SafariZoneNorthSignText"] = "PARC 2",
  ["_SafariZoneNorthTrainerTips1Text"] = "ASTUCE\012La Cabane Secrète\nest tout droit!",
  ["_SafariZoneNorthTrainerTips2Text"] = "ASTUCE\012Les POKéMON se\ncachent dans les\011hautes herbes!\012Explorez ces\nzones pour les\011faire sortir.",
  ["_SafariZoneNorthTrainerTips3Text"] = "ASTUCE\012Découvrez la\nCABANE SECRETE et\011gagnez une CS!",
  ["_SafariZoneSecretHouseFishingGuruHM03ExplanationText"] = "CS03 est SURF!\012Un POKéMON pourra\nte faire naviguer\011sur les flots!\012En plus, cette CS\npeut s'utiliser à\011l'infini!\012T'en as de la\nchance, mon p'tit\011bouchon!",
  ["_SafariZoneSecretHouseFishingGuruHM03NoRoomText"] = "Heu... Tu n'as\npas assez de\011place!",
  ["_SafariZoneSecretHouseFishingGuruReceivedHM03Text"] = "{PLAYER} obtient:\n{RAM:wStringBuffer}!",
  ["_SafariZoneSecretHouseFishingGuruYouHaveWonText"] = "Ah! Quand même!\012Tu es le premier\nà découvrir la\011CABANE SECRETE!\012J'avais peur que\npersonne ne gagne\011notre prix.\012Félicitations!\nTu as gagné!",
  ["_SafariZoneWestFindWardensTeethSignText"] = "AVIS\012Veuillez trouver\nla DENT D'OR du\011GARDIEN. Explorez\011les environs.\012Récompense\nassurée! \011Contactez le\011GARDIEN.",
  ["_SafariZoneWestRestHouseCooltrainerMText"] = "Un APPAT peut\nfaciliter vos\011captures.",
  ["_SafariZoneWestRestHouseScientistText"] = "Une PIERRE peut\nfaire fuir les\011POKéMON mais ils\011seront plus fa-\011ciles à capturer.",
  ["_SafariZoneWestRestHouseSignText"] = "ABRI",
  ["_SafariZoneWestRestHouseSilphWorkerFText"] = "J'ai cherché\ntoute la sainte\011journée mais j'ai\011rien capturé.",
  ["_SafariZoneWestSignText"] = "PARC 3\nEST: PARC CENTRAL",
  ["_SafariZoneWestTrainerTipsText"] = "ASTUCE\012Grand concours\norganisé:\012Cherchez la\nCABANE SECRETE!",
  ["_SaffronCityFightingDojoSignText"] = "DOJO",
  ["_SaffronCityGentlemanText"] = "Je suis venu ici\nen volant sur mon\011ROUCARNAGE après\011avoir lu les\011nouvelles de la\011SYLPHE.\012Tout est déjà\nfini? J'ai tout\011loupé?",
  ["_SaffronCityGymSignText"] = "SAFRANIA\nARENE POKéMON\011CHAMPION: MORGANE\012Maîtresse des\nforces psychiques",
  ["_SaffronCityMrPsychicsHouseSignText"] = "MAISON DE\nMR. PSY",
  ["_SaffronCityPidgeotText"] = "ROUCARNAGE: Rou!",
  ["_SaffronCityPokecenterGuyText1"] = "Pourquoi le\nCONSEIL des 4 ne\011vient pas casser\011les dents de la\011TEAM ROCKET?",
  ["_SaffronCityPokecenterGuyText2"] = "La TEAM ROCKET\nest partie! Alors\011c'est la fête!\011Youpi!",
  ["_SaffronCityRockerText"] = "J'ai vu le CHEF\nde la TEAM ROCKET\011s'enfuir de la\011SYLPHE.",
  ["_SaffronCityRocket1Text"] = "Kesstu veux?\nDu vent!",
  ["_SaffronCityRocket2Text"] = "Eul' CHEF dit\nqu'il contrôlera\011c'te ville!",
  ["_SaffronCityRocket3Text"] = "Bouge eud' là!",
  ["_SaffronCityRocket4Text"] = "SAFRANIA est à\nla TEAM ROCKET!",
  ["_SaffronCityRocket5Text"] = "Etre méchant,\nc'est mieux que\011d'se laver les\011dents!",
  ["_SaffronCityRocket6Text"] = "Tu m'as marché\nsul'pied, non?",
  ["_SaffronCityRocket7Text"] = "Avec la SYLPHE\ndans not' poche,\011les POKéMON du\011monde entier\011seront notre\011bizness!",
  ["_SaffronCityRocket8Text"] = "Moi....\nChuis un garde.\012Les nabots tout\nlouches, moi,\011j'les laisse pas\011passer!",
  ["_SaffronCityRocket9Text"] = "...\n(pionce)...\012Ha! Il dort!",
  ["_SaffronCityScientistText"] = "T'as tout cassé\nla ROCKET tout\011seul? Dingue!",
  ["_SaffronCitySignText"] = "SAFRANIA\nBelle et dorée,\011le commerce est\011ici prospère",
  ["_SaffronCitySilphCoLatestProductSignText"] = "Dernier produit\nde la SYLPHE!\012La date de sortie\nest encore à\011déterminer...",
  ["_SaffronCitySilphCoSignText"] = "SYLPHE SARL\nSIEGE SOCIAL",
  ["_SaffronCitySilphWorkerFText"] = "Tout le monde va\nvite revenir à\011SAFRANIA.",
  ["_SaffronCitySilphWorkerMText"] = "Ouais! La TEAM\nest partie!\011On peut enfin\011respirer!",
  ["_SaffronCityTrainerTips1Text"] = "ASTUCE\012TOTAL SOIN fait\ndisparaître tous\011les changements\011de statut comme\011le sommeil ou le\011gel.\012C'est un peu cher\nmais ça vaut le\011coup.",
  ["_SaffronCityTrainerTips2Text"] = "ASTUCE\012La SUPER BALL\naugmente les\011chances de\011capture.\012Faites un essai\nsur des POKéMON\011très vivaces.",
  ["_SaffronGateGuardGeeImThirstyText"] = "Je suis de garde\nmais je crève de\011soif!\012La route est\nfermée. Dégage.",
  ["_SaffronGateGuardImParchedText"] = "C'que j'ai soif!\nC'est dingue!\011...\011Hein? Tu m'donnes\011à boire? Dingue!\011Merci, p'tit!",
  ["_SaffronGateGuardThanksForTheDrinkText"] = "Salut! Merci\npour le verre!",
  ["_SaffronGateGuardYouCanGoOnThroughText"] = "\012...\nGlou gloup...\011...\011Glourp...\011Si tu veux aller\011à SAFRANIA...\011...glouarps...\011Tu peux passer...\011T'inquiète pas\011pour les autres\011gardes!",
  ["_SaffronGymChanneler1AfterBattleText"] = "Dans une baston,\nce qui est\011important, c'est\011la volonté de\011gagner!\012Si tu veux gagner\nface à MORGANE,\011concentre-toi sur\011la victoire!",
  ["_SaffronGymChanneler1BattleText"] = "MORGANE est une\npetite parvenue!\011Mais je l'aime\011bien!",
  ["_SaffronGymChanneler1EndBattleText"] = "Rhhâ!\nJ'suis nulle!",
  ["_SaffronGymChanneler2AfterBattleText"] = "Les attaques de\nmes POKéMON ne\011sont pas assez\011fortes!",
  ["_SaffronGymChanneler2BattleText"] = "L'aura du maître\ndéteint sur ses\011POKéMON.\012Tes POKéMON sont\nforts, non?",
  ["_SaffronGymChanneler2EndBattleText"] = "Argh!\nJe l'savais!",
  ["_SaffronGymChanneler3AfterBattleText"] = "J'avais prévu ce\nqui s'est passé.",
  ["_SaffronGymChanneler3BattleText"] = "Toi...Moi...\nNos POKéMON...\011FIGHT!",
  ["_SaffronGymChanneler3EndBattleText"] = "Puff!\nJ'ai perdu!",
  ["_SaffronGymGuideBeatSabrinaText"] = "Pouvoirs psy?\nHmmm...\012Si j'en avais, je\ngagnerais!",
  ["_SaffronGymGuideChampInMakingText"] = "Salut! Graine de\nchampion!\012Les POKéMON de\nMORGANE utilisent\011les pouvoirs de\011l'esprit!\012Les POKéMON du\ntype combat sont\011désavantagés!\012Ils deviennent\ndingues avant de\011pouvoir porter\011un coup!",
  ["_SaffronGymSabrinaMarshBadgeInfoText"] = "Avec le BADGE\nMARAIS, les\011POKéMON de niveau\01170 t'obéiront!\012Les POKéMON plus\npuissants seront\011incontrôlables\011lors des combats!\012Fais en sorte que\ntes POKéMON ne\011dépassent pas\011cette limite!\012Tiens! Prends ça\naussi!",
  ["_SaffronGymSabrinaPostBattleAdviceText"] = "Tout le monde est\nun peu médium!\011Il faut juste\011travailler ses\011dons!",
  ["_SaffronGymSabrinaReceivedMarshBadgeText"] = "Ha!\nJe suis surprise!\011Tu as gagné.\012C'est vrai, je\nn'ai pas fait de\011mon mieux! Tu\011mérites ta\011victoire!\012Tu gagnes le\nBADGE MARAIS!",
  ["_SaffronGymSabrinaReceivedTM46Text"] = "{PLAYER} obtient:\nCT46!",
  ["_SaffronGymSabrinaTM46NoRoomText"] = "Ton inventaire\nest plein!",
  ["_SaffronGymSabrinaText"] = "J'avais prédit\nton arrivée!\012J'ai des pouvoirs\npsychiques depuis\011l'enfance.\012J'ai appris à\nplier des\011cuillères par la\011force de mon\011esprit. C'est pas\011super utile, mais\011ça en jette!\012Je n'aime pas les\ncombats, mais si\011tu insistes, je\011vais te montrer\011mes pouvoirs!",
  ["_SaffronGymYoungster1AfterBattleText"] = "Les POKéMON psy\ncraignent les\011insectes et les\011fantômes!",
  ["_SaffronGymYoungster1BattleText"] = "Nos pouvoirs\noccultes te font\011peur?",
  ["_SaffronGymYoungster1EndBattleText"] = "Nyan!\nT'as pas l'air\011effrayé!",
  ["_SaffronGymYoungster2AfterBattleText"] = "MORGANE a\npulvérisé le\011grand MAITRE de\011KARATE!",
  ["_SaffronGymYoungster2BattleText"] = "La puissance sans\nmaîtrise n'est\011rien!",
  ["_SaffronGymYoungster2EndBattleText"] = "Huh!\nJ'appelle pas ça\011rien!",
  ["_SaffronGymYoungster3AfterBattleText"] = "Il y avait deux\nARENES POKéMON à\011SAFRANIA.\012Le DOJO KARATE a\nperdu son titre\011le jour où nous\011l'avons\011pulvérisé!",
  ["_SaffronGymYoungster3BattleText"] = "MORGANE est jeune\nmais elle est\011aussi notre\011CHAMPION!\012Tu vas en baver\ncomme un russe\011avant de\011l'atteindre!",
  ["_SaffronGymYoungster3EndBattleText"] = "Oups!\nJ'ai rien capté!",
  ["_SaffronGymYoungster4AfterBattleText"] = "J'ai lu dans ton\nesprit! C'est pas\011très bien rangé\011là d'dans!",
  ["_SaffronGymYoungster4BattleText"] = "Le CHAMPION de\nl'ARENE POKéMON\011de SAFRANIA est\011une médium psy!\012Tu veux voir\nMORGANE, hein?\011Je lis tes\011pensées... \011Vilain crapaud!",
  ["_SaffronGymYoungster4EndBattleText"] = "Arrrgh!",
  ["_SaffronMartCooltrainerFText"] = "Le RAPPEL est\ncoûteux mais il\011permet de\011réanimer un\011POKéMON K.O.!",
  ["_SaffronMartSuperNerdText"] = "Le MAX REPOUSSE\nfonctionne plus\011longtemps que le\011SUPEREPOUSSE!",
  ["_SaffronPidgeyHouseBrunetteGirlText"] = "Merci pour cette\nbelle lettre, à\011bientôt!\012Hé! R'garde pas\nc'que j'écris!\011J'suis amoureuse!",
  ["_SaffronPidgeyHousePaperText"] = "J'ai reçu comme\nrécompense un\011PP PLUS.\012Je l'ai utilisé\npour augmenter\011les PP des\011attaques de mes\011POKéMON!",
  ["_SaffronPidgeyHousePidgeyText"] = "ROUCOOL: Rourou!",
  ["_SaffronPidgeyHouseYoungsterText"] = "La COPIEUSE est\nmignonne! Je vais\011lui offrir une\011POKéPOUPEE!",
  ["_SaffronPokecenterBeautyText"] = "La puissance des\nPOKéMON est\011différente selon\011leur espèce.",
  ["_SaffronPokecenterGentlemanText"] = "La SYLPHE SARL\nest très connue.\011C'est pourquoi la\011TEAM ROCKET l'a\011investie!",
  ["_SandshrewDexEntry"] = "Il s'enterre dans\nles régions\narides et\012désertiques. Il\némerge seulement\npour chasser.",
  ["_SandslashDexEntry"] = "Il se roule en\nboule hérissée de\npiques s'il est\012menacé. Il peut\nainsi s'enfuir ou\nattaquer.",
  ["_SaveOptionText"] = "L'option SAUVER\nest sur l'écran\011du MENU.",
  ["_SavingEnergyText"] = "{USER}\nse concentre!",
  ["_ScaredText"] = "{RAM:wBattleMonNick} a peur\nde bouger!",
  ["_ScytherDexEntry"] = "Rapide et agile\ncomme un ninja,\nil se déplace si\012vite qu'il crée\nl'illusion d'être\nen groupe.",
  ["_SeadraDexEntry"] = "Il peut nager à\nl'envers en\nagitant ses\012petites nageoires\npectorales.",
