  ["_SilphCo10FSilphWorkerFQuietAboutMyCryingText"] = "Ne répète à\npersonne que j'ai\011pleuré!",
  ["_SilphCo11FBeautyText"] = "SECRETAIRE: Merci\nde nous avoir\011tous sauvés!\012Ton courage est\nexemplaire.",
  ["_SilphCo11FGiovanniText"] = "Ah, {PLAYER}!\nUne fois encore\011nos routes se\011croisent...\012Le PDG et moi-\nmême discutons\011d'une affaire\011très importante.\012Viens pas t'mêler\nde tout ça, mon\011bonhomme...\012Dégage ou...\nDéguste!",
  ["_SilphCo11FGiovanniYouRuinedOurPlansText"] = "NOoOoOoOon!\nNotre invasion de\011la SYLPHE est\011fichue!\012Mais la TEAM\nROCKET est\011invincible!\012{PLAYER}! N'oublie\njamais que tous\011les POKéMON sont\011pour la TEAM\011ROCKET!\012Je pars, mais...\nMa vengeance te\011fera bobo!",
  ["_SilphCo11FRocket1AfterBattleText"] = "Tu cherches\nl'embrouille?",
  ["_SilphCo11FRocket1BattleText"] = "Holà toi!\nPas bouger!",
  ["_SilphCo11FRocket1EndBattleText"] = "Non...\nPitié!",
  ["_SilphCo11FRocket2AfterBattleText"] = "Prends garde...\nLes POKéMON de\011mon chef sont\011terribles!",
  ["_SilphCo11FRocket2BattleText"] = "Halte! As-tu un\nrendez-vous en\011règle avec mon\011chef?",
  ["_SilphCo11FRocket2EndBattleText"] = "Gaah!\nCassé la tête!",
  ["_SilphCo11FSilphPresidentMasterBallDescriptionText"] = "PDG: Tu ne peux\nacheter ceci\011nulle part!\012C'est notre\nprototype secret:\011la MASTER BALL!\012Elle pourra\nattraper n'importe\011quel POKéMON!\012Alors utilise-la\navec sagesse.",
  ["_SilphCo11FSilphPresidentNoRoomText"] = "Tu n'as pas assez\nde place sur toi.",
  ["_SilphCo11FSilphPresidentReceivedMasterBallText"] = "{PLAYER} obtient:\n{RAM:wStringBuffer}!",
  ["_SilphCo11FSilphPresidentText"] = "PDG: Merci d'avoir\nsauvé la SYLPHE!\012Je n'oublierai\njamais ton\011haut fait!\012Tu mérites une\nrécompense!\012L'argent n'est\npas un problème\011pour moi!\012Tiens... Je crois\nque ceci te fera\011plaisir!",
  ["_SilphCo1FLinkReceptionistText"] = "Bienvenue!\012Le PRESIDENT est\ndans la salle du\011conseil, au 10ème\011étage!",
  ["_SilphCo2FRocket1AfterBattleText"] = "Les dalles en\nforme de diamant\011sont des\011téléporteurs!\012C'est de la super\ntechnologie!",
  ["_SilphCo2FRocket1BattleText"] = "Hé! Pas de\nmioches ici!",
  ["_SilphCo2FRocket1EndBattleText"] = "La vache!\nBalèze le p'tit!",
  ["_SilphCo2FRocket2AfterBattleText"] = "La SYLPHE SARL et\nla TEAM ROCKET\011vont fusionner!",
  ["_SilphCo2FRocket2BattleText"] = "Hé, p'tite tête!\nQu'est-ce tu\011fais là?",
  ["_SilphCo2FRocket2EndBattleText"] = "Oups,\nj'ai perdu!",
  ["_SilphCo2FScientist1AfterBattleText"] = "Je travaille pour\nla SYLPHE SARL et\011la TEAM ROCKET!",
  ["_SilphCo2FScientist1BattleText"] = "A l'aide! Je suis\nun employé de la\011SYLPHE SARL!",
  ["_SilphCo2FScientist1EndBattleText"] = "???\nComment t'as su\011que j'étais de\011La TEAM ROCKET?",
  ["_SilphCo2FScientist2AfterBattleText"] = "Trouve la\nsortie du\011Labyrinthe!",
  ["_SilphCo2FScientist2BattleText"] = "Hophop! Zone\nprivée, dégage!",
  ["_SilphCo2FScientist2EndBattleText"] = "OK.\nJ'suis battu!",
  ["_SilphCo2FSilphWorkerFReceivedTM36Text"] = "{PLAYER} obtient\n{RAM:wStringBuffer}!",
  ["_SilphCo2FSilphWorkerFTM36ExplanationText"] = "Voici la CT36:\nDESTRUCTION!\012C'est une attaque\ntrès puissante!\011Mais elle mettra\011K.O. le POKéMON\011qui l'utilise!!!",
  ["_SilphCo2FSilphWorkerFTM36NoRoomText"] = "Plus de place\npour cet objet!!!",
  ["_SilphCo3FRocketAfterBattleText"] = "Tu peux ouvrir\nles portes avec\011la CARTE MAGN.!",
  ["_SilphCo3FRocketBattleText"] = "T'occupe pas de\nnos affaires!",
  ["_SilphCo3FRocketEndBattleText"] = "Yaha!\nT'es trop fort!",
  ["_SilphCo3FScientistAfterBattleText"] = "Hmmm...\012J'aide la TEAM\nROCKET et ils\011me laissent\011étudier les\011POKéMON!",
  ["_SilphCo3FScientistBattleText"] = "Je préfère\nla TEAM ROCKET à\011la SYLPHE SARL!!!",
  ["_SilphCo3FScientistEndBattleText"] = "!!!\nTu m'as eu!",
  ["_SilphCo3FSilphWorkerMWhatShouldIDoText"] = "Je travaille pour\nla SYLPHE SARL.\011Que faire d'autre?",
