  ["_SilphCo4FScientistBattleText"] = "Mes POKéMON sont\nmes soldats!!!",
  ["_SilphCo4FScientistEndBattleText"] = "NAN!\nMes POKéMON!",
  ["_SilphCo4FSilphWorkerMImHidingText"] = "Chut! Tu n'vois\npas que je\011suis caché?",
