  ["_SilphCo7FScientistEndBattleText"] = "...\nFichu!",
  ["_SilphCo7FSilphWorkerM1HaveThisPokemonText"] = "Oh! Tu n'es pas\nun ROCKET! Es-tu\011là pour nous\011sauver? Merci!\012Prends donc ce\njoli POKéMON en\011cadeau.",
  ["_SilphCo7FSilphWorkerM1IsOurPresidentOkText"] = "Le chef de la\nTEAM ROCKET est\011dans la salle du\011conseil. Le PDG\011va-t-il bien?",
  ["_SilphCo7FSilphWorkerM1LaprasDescriptionText"] = "C'est un LOKHLASS.\nIl est très\011intelligent.\012Nous le gardions\ndans le labo,\011mais il sera\011mieux avec toi!\012Tu seras un bon\ndresseur pour\011LOKHLASS!\012Etant bon nageur,\nil pourra même te\011porter!",
  ["_SilphCo7FSilphWorkerM1SavedText"] = "De l'aide! Enfin!\nMerci!",
  ["_SilphCo7FSilphWorkerM2AfterTheMasterBallText"] = "La TEAM ROCKET\nvoulait s'emparer\011de la MASTER BALL\011pouvant attraper\011n'importe quel\011POKéMON!",
  ["_SilphCo7FSilphWorkerM2CancelledMasterBallText"] = "Le projet MASTER\nBALL fut annulé\011à cause de la\011TEAM ROCKET.",
  ["_SilphCo7FSilphWorkerM3ItWouldBeBadText"] = "Grâce au ciel la\nTEAM ROCKET ne\011put investir la\011SYLPHE ou voler\011nos POKéMON!",
