  ["_UndergroundPathRoute6GirlText"] = "Les gens font\nsouvent tomber\011des objets dans\011le SOUTERRAIN.",
  ["_UndergroundPathRoute7CopyUnusedGirlText"] = "Je veux aller au\ncentre commercial\011de CELADOPOLE...\012Mais, c'est plein\nde vilains voyous\011là-bas.",
  ["_UndergroundPathRoute7CopyUnusedGoesUnderSaffronText"] = "Le SOUTERRAIN\npasse sous\011SAFRANIA et\011débouche sur\011LAVANVILLE.\012Pour aller à\nAZURIA, va dans\011la maison de\011l'autre côté\011de la rue.",
  ["_UndergroundPathRoute7CopyUnusedMiddleAgedManText"] = "Tu veux acheter\nplein de trucs?\012Sors d'ici et va\nvers l'ouest!",
  ["_UndergroundPathRoute7CopyUnusedTeamRocketHadAHideoutText"] = "La TEAM ROCKET\npossède un abri\011secret dans\011CELADOPOLE!",
