  ["_VendingMachineText7"] = "Pas soif!",
  ["_VenomothDexEntry"] = "Les motifs ocre\nde ses ailes\nchangent en\012fonction de son\ntype de poison.",
  ["_VenonatDexEntry"] = "Il vit à l'ombre\ndes grands arbres\noù il mange des\012insectes. Il\nest attiré par la\nlumière.",
  ["_VenusaurDexEntry"] = "Sa plante mûrit\nen absorbant les\nrayons du soleil.\012Il migre souvent\nvers les endroits\nensoleillés.",
  ["_VermilionCityBeautyText"] = "La pollution,\nc'est mal!\012On dit que TADMORV\nse multiplie!",
  ["_VermilionCityGambler1DidYouSeeText"] = "As-tu vu\nL'OCEANE au port?",
  ["_VermilionCityGambler1SSAnneDepartedText"] = "L'OCEANE a\nlevé l'ancre!\012Il reviendra l'an\nprochain.",
  ["_VermilionCityGambler2Text"] = "Je construis un\nimmeuble sur ce\011terrain.\012Mes POKéMON\ndament le sol.",
  ["_VermilionCityGymSignText"] = "CARMIN SUR MER\nARENE POKéMON\011CHAMPION:\011MAJOR BOB\012Le Ricain\nSurvolté!",
  ["_VermilionCityHarborSignText"] = "PORT DE CARMIN",
  ["_VermilionCityMachopStompingTheLandFlatText"] = "\012Un MACHOC\npilonne le sol.",
  ["_VermilionCityMachopText"] = "MACHOC: Maaaaa!\nMachoooo!",
  ["_VermilionCityNoticeSignText"] = "AVIS!\012La ROUTE 12 peut\nêtre bloquée par\011un POKéMON\011endormi.\012Prendre la GROTTE\npour rejoindre\011LAVANVILLE.\012POLICE DE CARMIN\nSUR MER",
  ["_VermilionCityPokemonFanClubSignText"] = "FAN CLUB POKéMON\nTous les dingues\011de POKéMON sont\011bienvenus!",
  ["_VermilionCitySailor1DoYouHaveATicketText"] = "Bienvenue à bord\nde L'OCEANE!\012Puis-je voir\nvotre passe?",
  ["_VermilionCitySailor1FlashedTicketText"] = "{PLAYER} montre\nle passe et crâne\011à mort!\012Heu...merci!\nBienvenue à bord!",
  ["_VermilionCitySailor1ShipSetSailText"] = "L'OCEANE a\nlevé l'ancre.",
  ["_VermilionCitySailor1WelcomeToSSAnneText"] = "Bienvenue à bord\nde L'OCEANE!",
  ["_VermilionCitySailor1YouNeedATicketText"] = "{PLAYER} n'a pas\nde passe!\012Désolé!\012Il vous faut un\npasse pour monter\011à bord.",
  ["_VermilionCitySailor2Text"] = "L'OCEANE est\nun paquebot de\011luxe.\012Nous nous rendons\nà CARMIN SUR MER\011une fois par an.",
  ["_VermilionCitySignText"] = "CARMIN SUR MER\nLe port aux\011crépuscules\011flamboyants",
  ["_VermilionGymGentlemanAfterBattleText"] = "Les portes ne\ns'ouvrent pas?\012Le MAJOR BOB\nest prudent!",
  ["_VermilionGymGentlemanBattleText"] = "Dans l'armée, le\nMAJOR BOB était\011mon instructeur\011de combat!",
  ["_VermilionGymGentlemanEndBattleText"] = "Stop!\nTu es fort!",
  ["_VermilionGymGymGuideBeatLTSurgeText"] = "Wouh! Ce match\nétait survolté!",
  ["_VermilionGymGymGuideChampInMakingText"] = "Salut! Champion\nen herbe!\012Le MAJOR BOB a\nun surnom. On\011l'appelle...\011Le Ricain\011Survolté!\012Il est expert\nen POKéMON\011électriques!\012C'est pas bon\npour les POKéMON\011volants et\011aquatiques! Fais\011aussi gaffe aux\011éclairs pouvant\011paralyser!\012Le MAJOR BOB\nest très prudent!\012Il te faudra\nrésoudre une\011énigme pour\011arriver jusqu'à\011lui!",
  ["_VermilionGymLTSurgePostBattleAdviceText"] = "Un p'tit conseil,\ngamin!\012L'électricité est\ntrès puissante!\012Mais elle est\ninutile face à\011des POKéMON de\011la terre!",
  ["_VermilionGymLTSurgePreBattleText"] = "Hé, gamin!\nTu fais quoi là?\012Tu ne résisterais\npas longtemps\011en temps de\011guerre!\012Je vais te dire,\nmes POKéMON\011électriques m'ont\011sauvé la vie!\011Et ouais!\012Ils ont paralysé\nmes ennemis avec\011leurs éclairs!\011Une vraie\011boucherie!\012Y va t'arriver la\nmême chose!\011Compte tes dents!\011Tu vas morfler!",
  ["_VermilionGymLTSurgeReceivedTM24Text"] = "{PLAYER} reçoit:\n{RAM:wStringBuffer}!",
  ["_VermilionGymLTSurgeReceivedThunderBadgeText"] = "Whoo!\012Gard'vous! T'es\nun dur, mon p'tit\011gars!\012Très bien, prends\nle BADGEFOUDRE!",
  ["_VermilionGymLTSurgeTM24NoRoomText"] = "Revue d'paquetage\np'tit gars, ton\011inventaire est\011plein!",
  ["_VermilionGymLTSurgeThunderBadgeInfoText"] = "Le BADGEFOUDRE\naugmente la\011VITESSE de tes\011POKéMON!\012Il permet aussi\nà tes POKéMON\011de VOLER!\012Tu es un bon, mon\np'tit gars!\011Prends ça!",
  ["_VermilionGymSailorAfterBattleText"] = "Il y a une double\nsécurité! Voici\011un indice!\012Appuie sur un\nbouton et le 2ème\011est à côté!",
  ["_VermilionGymSailorBattleText"] = "C'est pas un\nendroit pour les\011gamins, ici!",
  ["_VermilionGymSailorEndBattleText"] = "Argh!\nTu m'as eu par\011surprise!",
  ["_VermilionGymSuperNerdAfterBattleText"] = "OK, je parle!\012Le MAJOR BOB a\ncaché des boutons\011pour ouvrir les\011portes...\011...Quequ'part!",
  ["_VermilionGymSuperNerdBattleText"] = "J'suis un poids\nplume, mais je\011suis bon avec\011l'électricité!",
  ["_VermilionGymSuperNerdEndBattleText"] = "Argh!\nJ'suis cuit!",
  ["_VermilionGymTrashFailText"] = "Une poubelle bien\ndégueulasse!\011Oups... Les\011verrouillages\011sont en place!",
  ["_VermilionGymTrashSuccessText1"] = "Oh! Un bouton\ndans la poubelle!\011Dingue!\012Le premier\nverrouillage est\011levé!",
  ["_VermilionGymTrashSuccessText2"] = "Hé! Un autre\nbouton dans la\011poubelle! Délire!\011On appuie!",
  ["_VermilionGymTrashSuccessText3"] = "Le deuxième\nverrouillage est\011levé!\012La porte s'ouvre!",
  ["_VermilionGymTrashText"] = "Mmmm!\nUn joli tas\011d'ordures...miam!",
  ["_VermilionMartCooltrainerFText"] = "Les POKéMON\npeuvent être\011gentils ou\011méchants, cela\011dépend de leur\011maître.",
  ["_VermilionMartCooltrainerMText"] = "Il y en a, des\ntrès méchants,\011qui utilisent les\011POKéMON pour\011voler les autres\011dresseurs.\012La TEAM ROCKET\nfait du trafic de\011POKéMON rares.\012Ils abandonnent\nsur le bord de la\011route les POKéMON\011trop faibles!\011Ouais, y sont\011comme ça chez les\011ROCKET.",
  ["_VermilionOldRodHouseFishingGuruDoYouLikeToFishText"] = "Je suis le...\nMAITRE PECHEUR!\012La pêche...moi...\nJ'adore ça!\012Et toi, p'tite\ntête?",
  ["_VermilionOldRodHouseFishingGuruFishingIsAWayOfLifeText"] = "\012Pêcher, c'est la\nvie! Et la vie,\011c'est la pêche!\012Du ruisseau\njusqu'aux océans,\011pêche, pêche et\011pêche encore!",
  ["_VermilionOldRodHouseFishingGuruHowAreTheFishBitingText"] = "B'jour à toi,\n{PLAYER}!\012Ca mord?\nHein? Hein?",
  ["_VermilionOldRodHouseFishingGuruNoRoomText"] = "Oh non!\012T'as plus d'place\npour mon cadeau!",
  ["_VermilionOldRodHouseFishingGuruTakeThisText"] = "Terrib'! Toi,\nj't'aime bien!\012Prends ça et...\nPêche! Pêche!\012{PLAYER} reçoit\n{RAM:wStringBuffer}!",
  ["_VermilionOldRodHouseFishingGuruThatsSoDisappointingText"] = "Oh...ben...\nC'est dommage...",
  ["_VermilionPidgeyHouseLetterText"] = "Cher JULIO,\nj'espère te voir\011très bientôt.\012On raconte que\nSAFRANIA a des\011problèmes avec la\011TEAM ROCKET.\012CARMIN SUR MER\nest paisible.",
  ["_VermilionPidgeyHousePidgeyText"] = "ROUCOOL: Rourou!",
  ["_VermilionPidgeyHouseYoungsterText"] = "Mon ROUCOOL va\napporter une\011lettre jusqu'à\011SAFRANIA au Nord!",
  ["_VermilionPokecenterFishingGuruText"] = "Deux POKéMON d'un\nmême niveau sont\011différents.\012Un POKéMON élevé\npar un dresseur\011est toujours plus\011fort qu'un\011POKéMON sauvage.\011Ouais mon gars!",
  ["_VermilionPokecenterGuyText"] = "C'est vrai qu'un\nPOKéMON de haut\011niveau est très\011puissant...\012Mais tout POKéMON\nest vulnérable\011face à un certain\011élément.\012Il n'y a donc pas\nde POKéMON de\011la mort qui tue.",
  ["_VermilionPokecenterSailorText"] = "Mon POKéMON est\nempoisonné! Il\011est tombé dans\011les pommes\011pendant que je\011marchais!",
  ["_VictoryRoad1FCooltrainerFAfterBattleText"] = "Perdre ça craint!",
  ["_VictoryRoad1FCooltrainerFBattleText"] = "Es-tu aussi fort\nque môa? ",
  ["_VictoryRoad1FCooltrainerFEndBattleText"] = "Oh!\nVilain!",
  ["_VictoryRoad1FCooltrainerMAfterBattleText"] = "T'es fort, \non a compris!",
  ["_VictoryRoad1FCooltrainerMBattleText"] = "Mmm...\nT'as l'air fort! \011Mais l'es-tu\011vraiment?",
  ["_VictoryRoad1FCooltrainerMEndBattleText"] = "OK.\nT'es fort.",
  ["_VictoryRoad2FCooltrainerMAfterBattleText"] = "Tu as le droit de\nparcourir la\011ROUTE VICTOIRE!",
  ["_VictoryRoad2FCooltrainerMBattleText"] = "Allez, viens\nmanger ta claque!",
  ["_VictoryRoad2FCooltrainerMEndBattleText"] = "Beuh!\nJ'me suis pris\011une claque!",
  ["_VictoryRoad2FHikerAfterBattleText"] = "Si tu es bloqué,\nessaie de bouger\011les rochers!",
  ["_VictoryRoad2FHikerBattleText"] = "La ROUTE VICTOIRE\nest l'épreuve\011finale de tout\011dresseur!",
  ["_VictoryRoad2FHikerEndBattleText"] = "Ouargh!",
  ["_VictoryRoad2FMoltresBattleText"] = "Yahoo!",
  ["_VictoryRoad2FSuperNerd1AfterBattleText"] = "{RIVAL} est aussi\narrivé ici!",
  ["_VictoryRoad2FSuperNerd1BattleText"] = "Alors comme ça,\ntu cherches les\011claques?",
  ["_VictoryRoad2FSuperNerd1EndBattleText"] = "Argh!\nT'as gagné!",
  ["_VictoryRoad2FSuperNerd2AfterBattleText"] = "En ce qui\nconcerne les\011POKéMON, j'suis\011le plus fort!\011... ... ...\011Du mooooonde!",
  ["_VictoryRoad2FSuperNerd2BattleText"] = "Si tu peux\nremporter ces\011épreuves,\011tu parviendras\011jusqu'au CONSEIL\011des 4!",
  ["_VictoryRoad2FSuperNerd2EndBattleText"] = "Ha!\nJ'y crois pas!",
  ["_VictoryRoad2FSuperNerd3AfterBattleText"] = "De nombreux\ndresseurs ont\011abandonné ici!",
  ["_VictoryRoad2FSuperNerd3BattleText"] = "La ROUTE de la\nVICTOIRE est une\011étape difficile?",
  ["_VictoryRoad2FSuperNerd3EndBattleText"] = "Bon...\nJ'ai perdu, non?",
  ["_VictoryRoad3FCooltrainerF1AfterBattleText"] = "Ben, j'suis pas\nsi forte que ça!",
  ["_VictoryRoad3FCooltrainerF1BattleText"] = "Je vais te\nmontrer ma\011puissance!",
  ["_VictoryRoad3FCooltrainerF1EndBattleText"] = "Non!\nJe suis furieuse!",
  ["_VictoryRoad3FCooltrainerF2AfterBattleText"] = "Bats-toi bien,\net tu seras\011un bon dresseur!",
  ["_VictoryRoad3FCooltrainerF2BattleText"] = "Un dresseur est\ntoujours en quête\011d'adversaires plus\011puissants!",
  ["_VictoryRoad3FCooltrainerF2EndBattleText"] = "Oh!\nT'es un dur toi!",
  ["_VictoryRoad3FCooltrainerM1AfterBattleText"] = "Tu as battu\nGIOVANNI de la\011TEAM ROCKET?",
  ["_VictoryRoad3FCooltrainerM1BattleText"] = "J'ai entendu\nparler d'un jeune\011prodige!",
  ["_VictoryRoad3FCooltrainerM1EndBattleText"] = "...\nC'était vrai!",
  ["_VictoryRoad3FCooltrainerM2AfterBattleText"] = "Ces dresseurs\nsont de la\011LIGUE POKéMON!\011Fais attention!",
  ["_VictoryRoad3FCooltrainerM2BattleText"] = "Seuls les élus\npeuvent passer!",
  ["_VictoryRoad3FCooltrainerM2EndBattleText"] = "Oh!\nJ'y crois pas!",
  ["_VictreebelDexEntry"] = "Il vit en\ncolonie dans la\njungle mais\012personne n'en est\njamais revenu\nvivant.",
  ["_VileplumeDexEntry"] = "Plus ses pétales\nsont grands,\nplus ils\012contiennent de\npollen toxique.",
  ["_ViridianBlackboardBurnText"] = "La BRULURE réduit\nla puissance et\011la vitesse. Elle\011inflige aussi des\011dégâts continus.\012La brûlure ne\ndisparaît pas\011après un combat.\012L'ANTI-BRULE\nsoigne les grands\011brûlés!",
  ["_ViridianBlackboardFrozenText"] = "Un POKéMON\nprisonnier des\011glaces reste\011immobile!\012Il reste gelé\nmême après la\011fin du combat.\012Un ANTIGEL peut\nréchauffer un\011POKéMON!",
  ["_ViridianBlackboardPoisonText"] = "Un POKéMON\nempoisonné voit\011son énergie se\011vider doucement.\012Le poison ne\ndisparaît pas\011après un combat.\012L'ANTIDOTE soigne\nle poison!",
  ["_ViridianBlackboardPrlzText"] = "La paralysie peut\nannuler certaines\011attaques!\012La paralysie ne\ndisparaît pas\011après un combat.\012L'ANTI-PARA\nsoigne toute\011paralysie!",
  ["_ViridianBlackboardSleepText"] = "Un POKéMON ne\npeut attaquer\011s'il est endormi!\012Un POKéMON reste\nendormi même\011après un combat.\012Un REVEIL peut\nle réveiller!",
  ["_ViridianCityFisherReceivedTM42Text"] = "{PLAYER} reçoit:\nCT42!",
  ["_ViridianCityFisherTM42ExplanationText"] = "CT42 contient\nDEVOREVE...\011...(pionce)...",
  ["_ViridianCityFisherTM42NoRoomText"] = "Tu es trop\nchargé.",
  ["_ViridianCityGambler1GymAlwaysClosedText"] = "Cette ARENE\nPOKéMON est\011toujours fermée.\012Mais qui en est\nle CHAMPION?",
  ["_ViridianCityGambler1GymLeaderReturnedText"] = "Le CHAMPION de\nl'ARENE de\011JADIELLE est de\011retour! Dingue!",
  ["_ViridianCityGirlHasntHadHisCoffeeYetText"] = "Papinou! Tu vas\nt'lever, ouais?\011T'as vidé la cave\011ou quoi?",
  ["_ViridianCityGirlWhenIGoShopText"] = "Je passe par la\nFORET DE JADE\011pour faire mes\011courses à\011ARGENTA.",
  ["_ViridianCityGymLockedText"] = "Les portes de\nl'ARENE sont\011fermées...",
  ["_ViridianCityGymSignText"] = "ARENE POKéMON\nde JADIELLE",
  ["_ViridianCityOldManHadMyCoffeeNowText"] = "Ahh... Un p'tit\nsomme, un bon\011café et hop! La\011pêche pour la\011journée!\012Mais bien sûr que\ntu peux passer!\012Mais au fait...\nT'es pressé?",
  ["_ViridianCityOldManKnowHowToCatchPokemonText"] = "Je vois que tu as\nun POKéDEX.\012Capture un\nPOKéMON et il\011sera mis à jour\011automatiquement.\012Qu...QUOI?\nTu ne sais pas\011comment attraper\011un POKéMON?\012J'vais t'montrer.",
  ["_ViridianCityOldManSleepyPrivatePropertyText"] = "Passage...\nINTERDIT!\012Propriété privée!",
  ["_ViridianCityOldManTimeIsMoneyText"] = "Le temps, c'est\nd'l'argent. Va.",
  ["_ViridianCityOldManYouNeedToWeakenTheTargetText"] = "D'abord, il faut\naffaiblir le\011POKéMON désiré.",
  ["_ViridianCityPokecenterGuyText"] = "Les CENTRES\nPOKéMON soignent\011tous les POKéMON\011blessés ou K.O.!",
  ["_ViridianCitySignText"] = "JADIELLE\nVerte comme\011l'espérance",
  ["_ViridianCityTrainerTips1Text"] = "ASTUCE\012Capturez des\nPOKéMON et\011agrandissez votre\011collection!\012Plus vous en\ncapturez, plus\011les combats sont\011faciles!",
  ["_ViridianCityTrainerTips2Text"] = "ASTUCE\012Les attaques sont\nlimitées par des\011PP (Points de\011Pouvoir).\012Pour disposer de\ntous vos PP,\011faites soigner\011vos POKéMON dans\011un CENTRE\011POKéMON!",
  ["_ViridianCityYoungster1Text"] = "Des POKé BALL!\nMais... T'as des\011POKéMON!\012C'est cool de\npouvoir s'en\011servir quand on\011veut, hein?",
  ["_ViridianCityYoungster2YouWantToKnowAboutText"] = "Tu veux tout\nsavoir sur les 2\011types de chenille\011POKéMON?",
  ["_ViridianForestLeavingSignText"] = "VOUS QUITTEZ LA\nFORET DE JADE.\011VOUS ALLEZ VERS\011ARGENTA.",
  ["_ViridianForestNorthGateGrampsText"] = "As-tu remarqué\nles buissons sur\011la route?\012Une technique\nsecrète de\011POKéMON peut les\011couper.",
  ["_ViridianForestNorthGateSuperNerdText"] = "De nombreux\nPOKéMON vivent\011uniquement dans\011les forêts ou les\011cavernes.\012Cherche bien\npartout pour tous\011les avoir!",
  ["_ViridianForestSouthGateGirlText"] = "Vas-tu dans la\nFORET DE JADE,\011mon poussin? Fais\011bien attention,\011c'est un vrai\011labyrinthe!",
  ["_ViridianForestSouthGateLittleGirlText"] = "RATTATA est\npetit mais il est\011vicieux! En as-tu\011capturé un?",
  ["_ViridianForestTrainerTips1Text"] = "ASTUCE\012Pour éviter les\ncombats, ne \011marchez pas dans\011les hautes herbes!",
  ["_ViridianForestTrainerTips2Text"] = "ASTUCE\012Pour évaluer\nvotre POKéDEX,\011appelez le Prof.\011Chen via un PC!",
  ["_ViridianForestTrainerTips3Text"] = "ASTUCE\012Interdiction de\ncapturer les\011POKéMON d'un\011autre dresseur!\011La capture se\011fait à l'état\011sauvage!",
  ["_ViridianForestTrainerTips4Text"] = "ASTUCE\012Un POKéMON\nblessé se capture\011plus facilement!\012En pleine forme,\nil peut s'enfuir!",
  ["_ViridianForestUseAntidoteSignText"] = "L'ANTIDOTE vendu\ndans les\011BOUTIQUES PKMN\011guérit du poison.",
  ["_ViridianForestYoungster1Text"] = "Je suis ici\navec des amis!\012Ils sont ici\npour se battre!",
  ["_ViridianForestYoungster2AfterBattleText"] = "Chut! Tu fais\npeur aux\011insectes...",
  ["_ViridianForestYoungster2BattleText"] = "Hé! Mais tu as\ndes POKéMON!\011Yah! A l'attaque!",
  ["_ViridianForestYoungster2EndBattleText"] = "NON!\nCHENIPAN n'y\011arrivera pas!",
  ["_ViridianForestYoungster3AfterBattleText"] = "Fichtre! J'vais\nen choper des\011plus balèzes!",
  ["_ViridianForestYoungster3BattleText"] = "Haha! Un dresseur\nde POKéMON, un\011vrai, ne se\011débine jamais!!!",
  ["_ViridianForestYoungster3EndBattleText"] = "Oups!\nN'en n'a plus des\011POKéMON, moi!",
  ["_ViridianForestYoungster4AfterBattleText"] = "Tu trouveras\npeut-être des\011objets par terre!\012Je cherche les\nobjets que j'ai\011laissé tomber...",
  ["_ViridianForestYoungster4BattleText"] = "Hop, hop! Minute!\nOn n'est pas\011pressé!",
  ["_ViridianForestYoungster4EndBattleText"] = "Houlà!\nJ'abandonne!\011T'es trop fort!",
  ["_ViridianForestYoungster5Text"] = "J'suis à court de\nPOKé BALL!\011Je ne peux plus\011attraper de\011POKéMON!\012Il t'en faut\ntoujours un max!",
  ["_ViridianGymCooltrainerM1AfterBattleText"] = "Il faut que tu\nsois fort pour te\011mesurer au...\011CHAMPION!",
  ["_ViridianGymCooltrainerM1BattleText"] = "Hé! Tu dois être\ncrevé, non? ",
  ["_ViridianGymCooltrainerM1EndBattleText"] = "Ha!\nJ'suis essoufflé!",
  ["_ViridianGymCooltrainerM2AfterBattleText"] = "Le CHAMPION va\nme taper dessus!",
  ["_ViridianGymCooltrainerM2BattleText"] = "Je vais t'écraser\navec style et\011élégance!",
  ["_ViridianGymCooltrainerM2EndBattleText"] = "...\nTout perdu!",
  ["_ViridianGymCooltrainerM3AfterBattleText"] = "Tu ne pourras\naccéder à la\011LIGUE POKéMON\011seulement en\011battant notre\011CHAMPION!",
  ["_ViridianGymCooltrainerM3BattleText"] = "L'ARENE de\nJADIELLE était\011fermée depuis\011longtemps, mais\011le CHAMPION est\011enfin revenu!",
  ["_ViridianGymCooltrainerM3EndBattleText"] = "!!!\nDéfaite!",
  ["_ViridianGymGiovanniEarthBadgeInfoText"] = "Grâce au BADGE\nTERRE tous les\011POKéMON obéiront\011à tes ordres!\012Il est le\ntémoignage de ta\011grande maîtrise\011des POKéMON!\012Tu pourras ainsi\naccéder à la\011LIGUE POKéMON!\012C'est un cadeau\nque je te fais.\011Va maintenant,\011et deviens le\011plus grand des\011dresseurs!",
  ["_ViridianGymGiovanniPostBattleAdviceText"] = "OK, j'ai perdu!\nJe ne suis pas\011digne d'être le\011chef de la TEAM\011ROCKET! Ainsi,\011son existence\011s'achève avec ma\011défaite!\012Je vais me\nretirer, loin, en\011ermite, pour\011étudier les\011POKéMON!\012Un jour, nos\nchemins se\011croiseront à\011nouveau! Adieu!",
  ["_ViridianGymGiovanniPreBattleText"] = "Fwahaha! Te voici\ndans mon repaire!\012Je voulais\nreformer la TEAM\011ROCKET ici!\012Mais tu as encore\ntout fait rater!\011Je suis furieux\011et ça sent pas\011bon pour toi!\012Une fois de plus\ntu oses me\011défier, moi, le\011grand GIOVANNI!\011Mais aujourd'hui,\011tu vas déguster!",
  ["_ViridianGymGiovanniReceivedEarthBadgeText"] = "Ah!\nVoilà ce que\011j'appelle du\011combat! Tu as\011gagné! En\011récompense voici\011le BADGE TERRE!",
  ["_ViridianGymGiovanniReceivedTM27Text"] = "{PLAYER} reçoit\nCT27!",
  ["_ViridianGymGiovanniTM27ExplanationText"] = "\012CT27: ABIME!\nCette attaque\011peut mettre hors\011combat un POKéMON\011en un seul coup!\012Je l'ai inventée\nil y a bien\011longtemps...",
  ["_ViridianGymGiovanniTM27NoRoomText"] = "Votre inventaire\nest plein!",
  ["_ViridianGymGuidePostBattleText"] = "Quoi?! C'était\nGIOVANNI le\011CHAMPION?\011Ben ça alors!",
  ["_ViridianGymGuidePreBattleText"] = "Salut! Champion\nen herbe!\012Même moi, je ne\nsais pas qui est\011le CHAMPION de\011JADIELLE!\012Le combat qui\nt'attend sera le\011plus dur de tous!\012Le dresseur de\ncette ARENE aime\011les POKéMON du\011type SOL!",
  ["_ViridianGymHiker1AfterBattleText"] = "Grouargh!",
  ["_ViridianGymHiker1BattleText"] = "Groaar!\nColère! Viens\011te battre!",
  ["_ViridianGymHiker1EndBattleText"] = "Rargh!",
  ["_ViridianGymHiker2AfterBattleText"] = "Mes POKéMON sont\ndes karatékas...",
  ["_ViridianGymHiker2BattleText"] = "Le Karaté est\nl'art martial\011ultime!",
  ["_ViridianGymHiker2EndBattleText"] = "Yaha!",
  ["_ViridianGymHiker3AfterBattleText"] = "La LIGUE POKéMON?\nToi? Hahahahah!!!\011T'es un rigolo!",
  ["_ViridianGymHiker3BattleText"] = "J'suis le ROI du\nKARATE! Ton\011destin repose\011entre mes mains!",
  ["_ViridianGymHiker3EndBattleText"] = "Yaah!",
  ["_ViridianGymRocker1AfterBattleText"] = "Sais-tu qui est\nnotre CHAMPION?",
  ["_ViridianGymRocker1BattleText"] = "Avec mes POKéMON\nje fais de la\011jolie musique!",
  ["_ViridianGymRocker1EndBattleText"] = "Tu es\ntrès fort!",
  ["_ViridianGymRocker2AfterBattleText"] = "Attends! Je ne\nfaisais pas\011attention!",
  ["_ViridianGymRocker2BattleText"] = "Tes POKéMON vont\nse courber sous\011mes coups de\011fouet!",
  ["_ViridianGymRocker2EndBattleText"] = "Aïee!",
  ["_ViridianMartClerkParcelQuestText"] = "Tu connais le\nPROF. CHEN?\012Sa commande vient\nd'arriver.\011Peux-tu la lui\011apporter?\012{PLAYER} obtient\nle COLIS DE CHEN!",
  ["_ViridianMartClerkSayHiToOakText"] = "Cool! Tu diras\nbonjour au PROF.\011CHEN de ma part!",
  ["_ViridianMartClerkYouCameFromPalletTownText"] = "Hé! Tu viens de\nBOURG PALETTE?",
  ["_ViridianMartCooltrainerMText"] = "Plus de POTIONS!\nNous sommes en\011rupture de stock.",
  ["_ViridianMartYoungsterText"] = "On vend des\nANTIDOTES dans\011cette boutique.",
  ["_ViridianNicknameHouseBaldingGuyText"] = "Trouver des noms,\nc'est rigolo\011mais c'est dur!\012Les noms les plus\nsimples sont les\011plus faciles.",
  ["_ViridianNicknameHouseLittleGirlText"] = "Mon pôpa aime les\nPOKéMON aussi.",
  ["_ViridianNicknameHouseSpearowText"] = "PIAFFY: Tetweet!",
  ["_ViridianNicknameHouseSpearySignText"] = "PIAFABEC\nNom: PIAFFY",
  ["_ViridianPokecenterCooltrainerMText"] = "Il y a un CENTRE\nPOKéMON dans\011chaque ville.\012Tu peux y soigner\ngratuitement tes\011POKéMON!",
  ["_ViridianPokecenterGentlemanText"] = "Tu peux utiliser\nle PC.\012C'est l'hôtesse\nqui me l'a dit!\011Elle est cool!",
  ["_ViridianSchoolBlackboardText1"] = "Le tableau décrit\nles changements\011de STATUT des\011POKéMON pendant\011un combat.",
  ["_ViridianSchoolBlackboardText2"] = "Quel chapitre\nvoulez-vous lire?",
  ["_ViridianSchoolHouseBrunetteGirlText"] = "Pfouh! J'essaie\nd'apprendre mes\011leçons.",
  ["_ViridianSchoolHouseCooltrainerFText"] = "OK!\012Lis attentivement\nle tableau avant\011de partir!",
  ["_ViridianSchoolNotebookText1"] = "Vous examinez le\njournal!\012Première page...\012Les POKé BALL\npeuvent capturer\011les POKéMON.\012Jusqu'à 6\nPOKéMON sont\011transportables.\012Les personnes\ns'occupant des\011POKéMON sont\011des dresseurs de\011POKéMON.",
  ["_ViridianSchoolNotebookText2"] = "Deuxième page...\012Un POKéMON\nsauvage et en\011pleine forme est\011difficile à\011capturer, alors\011affaiblissez-le!\012Le poison, la\nbrûlure et les\011autres types de\011dégâts sont aussi\011efficaces!",
  ["_ViridianSchoolNotebookText3"] = "Troisième page...\012Le but de chaque\ndresseur est\011d'affronter les\011autres dresseurs\011dans des combats\011de POKéMON.\012Les combats se\ntiennent en\011permanence dans\011les ARENES\011POKéMON.",
  ["_ViridianSchoolNotebookText4"] = "Quatrième page...\012Le rêve de chaque\ndresseur est de\011vaincre les 8\011CHAMPIONS des\011différentes\011ARENES POKéMON.\012Ces victoires\ndonnent le droit\011d'affronter...\012Le CONSEIL des 4\nde la LIGUE\011POKéMON!",
  ["_ViridianSchoolNotebookText5"] = "FILLE: Hé! Ne lis\npas mon journal!",
